/* Câu hỏi các đề Tin học lớp 6 có sẵn. Danh mục (tên, khối, môn, số phút, số câu): data/banks/index.js.
   App chỉ tải file này khi mở một đề trong đó. Dạng câu hỏi: xem đầu data/banks/index.js. */
window.ONTAP_SEED_QUESTIONS = Object.assign(window.ONTAP_SEED_QUESTIONS || {}, {
  /* ---------- Tin học 6 · Kiểm tra cuối học kì I (Kết nối tri thức) ----------
     Phạm vi học kì I ghi ở note. Câu tự soạn. Mức độ lv của đề 1 ghi ở Phiên N6 (câu, chủ đề giữ nguyên). Hai đề là kho của đề
     ngẫu nhiên "tin6-ck1-ngau-nhien" (không có câu riêng nên không ghi vào file này; ma trận ở data/banks/index.js). Câu ở hai ô
     khác nhau của ma trận có thể cùng được rút vào một đề, nên đề bài, các lựa chọn, lời giải không ghi sẵn đáp án của câu khác.
     Cách xếp mức (cả hai đề): nêu khái niệm, tên phần mềm, thiết bị, đơn vị, chức năng là Biết; phân biệt các khái niệm gần nhau
     (thông tin – vật mang tin, thiết bị đầu cuối – thiết bị kết nối), so sánh dung lượng, giải thích, đánh giá một nhận định là
     Hiểu; tính và đổi đơn vị dung lượng, chọn từ khóa, sắp xếp các bước làm, xử lí tình huống trên mạng là Vận dụng. */
  "tin6-ck1-de1": {
    note: "Sách Kết nối tri thức, học kì I (Bài 1–9): thông tin và dữ liệu, xử lí thông tin, thông tin trong máy tính; mạng máy tính, Internet; mạng thông tin toàn cầu, tìm kiếm thông tin trên Internet, thư điện tử; an toàn thông tin trên Internet. Đề không có phần thực hành trên máy. Có lời giải từng câu.",
    questions: [
      { topic: "Thông tin và dữ liệu", type: "mc", q: "Nghe loa phát thanh ở sân trường, Hùng biết chiều nay lớp được nghỉ học thêm. Điều Hùng biết được là:", o: ["Thông tin", "Dữ liệu", "Vật mang tin", "Thiết bị ra"], x: "Tiếng nói phát ra từ loa là dữ liệu dạng âm thanh. Hiểu biết Hùng có được từ dữ liệu đó (chiều nay được nghỉ học thêm) là thông tin.", lv: 1 },
      { topic: "Thông tin và dữ liệu", type: "mc", q: "Vật nào dưới đây là vật mang tin?", o: ["Chiếc USB", "Nội dung bản tin thời tiết", "Tiếng chuông báo hết giờ", "Kết quả của một phép tính"], x: "Vật mang tin là phương tiện dùng để lưu trữ và truyền tải thông tin, như USB, đĩa CD, giấy, sách vở. Nội dung bản tin, tiếng chuông, kết quả phép tính là thông tin, dữ liệu chứ không phải vật mang tin.", lv: 2 },
      { topic: "Thông tin và dữ liệu", type: "tf", q: "Dữ liệu có thể được thể hiện dưới dạng chữ, số, hình ảnh hoặc âm thanh.", a: true, x: "Dữ liệu có thể là con số, văn bản, hình ảnh, âm thanh… Máy tính xử lí dữ liệu để cho ra thông tin.", lv: 1 },
      { topic: "Xử lí thông tin", type: "mc", q: "Quá trình xử lí thông tin gồm các hoạt động:", o: ["Thu nhận, xử lí, lưu trữ và truyền thông tin", "Bật máy tính, mở phần mềm, gõ bàn phím và tắt máy", "Nhìn, nghe, nói và viết", "Tìm kiếm, sao chép, dán và in"], x: "Con người và máy tính đều xử lí thông tin qua các hoạt động: thu nhận, xử lí, lưu trữ và truyền thông tin.", lv: 1 },
      { topic: "Xử lí thông tin", type: "mc", q: "Thiết bị nào dưới đây là thiết bị vào của máy tính?", o: ["Bàn phím", "Màn hình", "Loa", "Máy in"], x: "Thiết bị vào dùng để đưa thông tin vào máy tính: bàn phím, chuột, micro, máy quét… Màn hình, loa, máy in là thiết bị ra.", lv: 1 },
      { topic: "Xử lí thông tin", type: "mc", q: "Trong máy tính, bộ phận thực hiện việc xử lí thông tin là:", o: ["Bộ xử lí (CPU)", "Màn hình cảm ứng", "Chuột", "Ổ đĩa cứng"], x: "Bộ xử lí (CPU) xử lí thông tin. Ổ đĩa cứng thuộc bộ nhớ, dùng để lưu trữ; chuột là thiết bị vào; màn hình là thiết bị ra.", lv: 1 },
      { topic: "Thông tin trong máy tính", type: "mc", q: "Trong máy tính, thông tin được biểu diễn bằng:", o: ["Dãy bit gồm các kí hiệu 0 và 1", "Các chữ cái từ A đến Z", "Các chữ số từ 0 đến 9", "Các màu sắc và hình vẽ khác nhau trên màn hình"], x: "Máy tính dùng dãy bit, mỗi bit là 0 hoặc 1, để biểu diễn mọi thông tin: số, chữ, hình ảnh, âm thanh.", lv: 1 },
      { topic: "Thông tin trong máy tính", type: "fill", q: "1 byte = ___ bit.", ans: ["8", "tám"], x: "Byte là đơn vị đo dung lượng thông tin, 1 byte gồm 8 bit.", lv: 1 },
      { topic: "Thông tin trong máy tính", type: "mc", q: "Trong các đơn vị đo dung lượng sau, đơn vị nào lớn nhất?", o: ["Terabyte (TB)", "Gigabyte (GB)", "Megabyte (MB)", "Kilobyte (KB)"], x: "Từ nhỏ đến lớn: byte < KB < MB < GB < TB. Mỗi đơn vị gấp 1 024 lần (khoảng một nghìn lần) đơn vị liền trước.", lv: 2 },
      { topic: "Thông tin trong máy tính", type: "mc", q: "Một chiếc máy ghi âm có bộ nhớ còn trống 8 GB. Mỗi bản ghi âm một buổi học dài khoảng 4 MB. Máy chứa thêm được khoảng bao nhiêu bản ghi âm như vậy?", o: ["Khoảng 2 000 bản", "Khoảng 200 bản", "Khoảng 32 bản", "Khoảng 20 000 bản"], x: "8 GB = 8 × 1 024 MB = 8 192 MB. Số bản ghi âm: 8 192 : 4 = 2 048, tức khoảng 2 000 bản.", lv: 3 },
      { topic: "Mạng máy tính", type: "mc", q: "Hai máy tính ở hai phòng trong nhà Minh được nối với nhau bằng một sợi cáp mạng để gửi tệp cho nhau. Nhận xét nào đúng?", o: ["Hai máy tính đó đã tạo thành một mạng máy tính", "Chưa phải mạng máy tính vì chỉ có hai máy", "Chưa phải mạng máy tính vì chưa kết nối Internet", "Chưa phải mạng máy tính vì không có máy in"], x: "Chỉ cần hai máy tính được kết nối để truyền thông tin cho nhau là đã có một mạng máy tính. Mạng không bắt buộc phải có Internet hay máy in.", lv: 1 },
      { topic: "Mạng máy tính", type: "mc", q: "Thiết bị nào dưới đây là thiết bị kết nối trong mạng máy tính?", o: ["Bộ định tuyến (router wifi)", "Máy in của phòng học", "Điện thoại thông minh", "Máy tính xách tay của cô giáo"], x: "Mạng máy tính gồm thiết bị đầu cuối (máy tính, điện thoại, máy in…), thiết bị kết nối (dây cáp mạng, bộ chuyển mạch, bộ định tuyến không dây…) và phần mềm mạng.", lv: 2 },
      { topic: "Mạng máy tính", type: "tf", q: "Nhờ mạng máy tính, nhiều máy tính trong phòng học có thể dùng chung một máy in.", a: true, x: "Một lợi ích của mạng máy tính là dùng chung tài nguyên như máy in, dữ liệu, đường truyền Internet.", lv: 2 },
      { topic: "Internet", type: "mc", q: "Mạng của phòng tin học ở trường nối 20 máy tính với nhau. Internet khác mạng đó ở chỗ:", o: ["Internet kết nối rất nhiều mạng máy tính trên khắp thế giới", "Internet chỉ gồm một máy tính rất mạnh", "Internet không cần đến thiết bị kết nối", "Internet chỉ dùng được trong trường học"], x: "Mạng của phòng tin học chỉ nối các máy trong một phòng. Internet là mạng liên kết các mạng máy tính trên khắp thế giới, nhờ đó người dùng ở mọi nơi tìm kiếm, chia sẻ và trao đổi được thông tin.", lv: 1 },
      { topic: "Internet", type: "mc", q: "Đặc điểm nào sau đây KHÔNG phải là đặc điểm của Internet?", o: ["Thuộc về một công ty duy nhất", "Có tính toàn cầu, kết nối khắp thế giới", "Có tính tương tác giữa người dùng", "Dễ tiếp cận"], x: "Internet có tính toàn cầu, tính tương tác, tính dễ tiếp cận và không thuộc quyền sở hữu của ai.", lv: 2 },
      { topic: "Mạng thông tin toàn cầu", type: "mc", q: "Phần mềm nào dưới đây là trình duyệt web?", o: ["Google Chrome", "Microsoft Word", "Paint", "Microsoft PowerPoint"], x: "Trình duyệt web là phần mềm dùng để truy cập các trang web, ví dụ Google Chrome, Microsoft Edge, Firefox, Cốc Cốc. Word dùng để soạn văn bản, Paint để vẽ, PowerPoint để làm bài trình chiếu.", lv: 1 },
      { topic: "Mạng thông tin toàn cầu", type: "mc", q: "Thư viện thành phố có trang giới thiệu, trang mục lục sách, trang tin sự kiện… trên Internet; các trang này liên quan với nhau và được truy cập qua cùng một địa chỉ. Tập hợp các trang web đó được gọi là:", o: ["Một website", "Một trình duyệt", "Một máy tìm kiếm", "Một hộp thư điện tử"], x: "Website là tập hợp các trang web liên quan, được truy cập qua một địa chỉ. Trình duyệt và máy tìm kiếm không phải là tập hợp các trang của thư viện; hộp thư điện tử dùng để gửi, nhận thư.", lv: 1 },
      { topic: "Tìm kiếm thông tin trên Internet", type: "mc", q: "Bạn muốn biết về các loài chim di cư qua Việt Nam nhưng chưa biết trang web nào có thông tin này. Bạn nên dùng công cụ nào để có danh sách liên kết tới các trang web liên quan?", o: ["Bing (bing.com)", "Thanh đánh dấu của trình duyệt", "Microsoft Word", "Gmail"], x: "Bing là một máy tìm kiếm: website đặc biệt, gõ từ khóa thì nhận được danh sách liên kết tới các trang web có từ khóa đó. Thanh đánh dấu chỉ lưu địa chỉ những trang đã biết; Word dùng để soạn văn bản; Gmail là dịch vụ thư điện tử.", lv: 1 },
      { topic: "Tìm kiếm thông tin trên Internet", type: "mc", q: "Bạn muốn tìm cách chăm sóc cây xương rồng. Từ khóa nào phù hợp nhất?", o: ["chăm sóc cây xương rồng", "cây", "cách làm", "giá bán cây xương rồng tại chợ"], x: "Từ khóa nên ngắn gọn nhưng nêu đúng nội dung cần tìm. Từ khóa quá chung như “cây”, “cách làm” cho ra rất nhiều kết quả không liên quan.", lv: 3 },
      { topic: "Thư điện tử", type: "mc", q: "Trong địa chỉ thư điện tử lan.tin6@truonghoc.edu.vn, phần “truonghoc.edu.vn” là:", o: ["Địa chỉ máy chủ thư điện tử", "Tên đăng nhập của người dùng", "Mật khẩu của hộp thư", "Tiêu đề của bức thư"], x: "Địa chỉ thư điện tử có dạng <tên đăng nhập>@<địa chỉ máy chủ thư điện tử>. Phần trước @ (lan.tin6) là tên đăng nhập, phần sau @ (truonghoc.edu.vn) là địa chỉ máy chủ do nhà cung cấp dịch vụ quy định. Mật khẩu không bao giờ nằm trong địa chỉ thư.", lv: 2 },
      { topic: "Thư điện tử", type: "tf", q: "Có thể gửi kèm tệp ảnh, tệp văn bản theo thư điện tử.", a: true, x: "Thư điện tử có thể đính kèm tệp (ảnh, văn bản, bài trình chiếu…) và gửi cùng lúc cho nhiều người.", lv: 1 },
      { topic: "Thư điện tử", type: "mc", q: "Cô giáo gửi bài tập qua thư điện tử. Tối nay nhà Hải bị mất kết nối Internet. Điều gì xảy ra với Hải?", o: ["Hải phải chờ có kết nối Internet mới mở hộp thư đọc được bài tập", "Hải vẫn đọc được thư mới vì thư điện tử không cần mạng", "Bưu điện sẽ mang bản in bức thư đến nhà Hải", "Cô giáo phải gửi lại thư mỗi giờ cho đến khi Hải đọc"], x: "Một nhược điểm của thư điện tử là phải dùng thiết bị có kết nối mạng mới gửi, nhận, đọc được thư. Thư điện tử không do bưu điện chuyển, và người gửi không phải gửi lại.", lv: 2 },
      { topic: "An toàn thông tin trên Internet", type: "mc", q: "Mật khẩu nào dưới đây mạnh nhất?", o: ["Tr@ng6a#2026", "123456", "matkhau", "minhanhoclop6a"], x: "Mật khẩu mạnh thì dài, có cả chữ hoa, chữ thường, chữ số và kí hiệu đặc biệt, khó đoán. “123456”, “matkhau” rất dễ bị đoán ra; “minhanhoclop6a” tuy dài nhưng chỉ có chữ thường, ghép từ tên và lớp nên cũng dễ đoán.", lv: 3 },
      { topic: "An toàn thông tin trên Internet", type: "mc", q: "Một tài khoản mạng xã hội mang tên chị họ của Lan nhắn tin hỏi tên trường, lớp và giờ tan học của Lan. Lan nên làm gì?", o: ["Chưa trả lời, gọi điện hoặc gặp trực tiếp chị để hỏi lại xem có đúng chị nhắn không", "Trả lời ngay vì đó là tài khoản của người thân", "Chỉ gửi tên trường, không gửi giờ tan học", "Đăng các thông tin đó lên trang cá nhân để ai cần thì xem"], x: "Trên mạng không biết chắc ai đứng sau một tài khoản; tài khoản của người quen cũng có thể bị kẻ xấu dùng. Thông tin cá nhân chỉ chia sẻ khi cần và sau khi đã hỏi lại người đó bằng điện thoại hoặc gặp trực tiếp; có điều gì lạ thì báo bố mẹ, thầy cô.", lv: 3 },
      { topic: "An toàn thông tin trên Internet", type: "tf", q: "Khi dùng máy tính ở nơi công cộng, cần đăng xuất tài khoản sau khi dùng xong.", a: true, x: "Nếu quên đăng xuất, người dùng máy sau có thể vào tài khoản của bạn và lấy thông tin cá nhân.", lv: 2 }
    ]
  },

  /* Đề 2 (Phiên N6): cùng phạm vi, đủ 9 chủ đề của đề 1 (chữ chủ đề giữ nguyên), chia đúng theo ma trận của đề ngẫu nhiên:
     10 Biết, 8 Hiểu, 7 Vận dụng (đề 1 có 13 – 8 – 4, nên đề 2 thêm câu Vận dụng: đổi đơn vị dung lượng, mở trang web, sắp xếp
     các bước tìm kiếm thông tin và gửi thư điện tử, chọn nguồn tin, xử lí tin nhắn lừa đảo). Dạng câu theo khung Công văn 7991:
     nhiều lựa chọn, đúng/sai 4 ý, trả lời ngắn bằng số, nối cột (thiết bị – chức năng, dịch vụ – công dụng), sắp xếp. */
  "tin6-ck1-de2": {
    note: "Sách Kết nối tri thức, học kì I (Bài 1–9): thông tin và dữ liệu, xử lí thông tin, thông tin trong máy tính; mạng máy tính, Internet; mạng thông tin toàn cầu, tìm kiếm thông tin trên Internet, thư điện tử; an toàn thông tin trên Internet. Có trường dạy Bài 9 ở học kì II, phụ huynh đối chiếu với đề cương của trường. Đề không có phần thực hành trên máy. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Có lời giải từng câu.",
    questions: [
      { topic: "Thông tin và dữ liệu", type: "mc", q: "Thông tin có vai trò như thế nào đối với con người?", o: ["Đem lại hiểu biết, giúp con người lựa chọn đúng đắn", "Thay thế hoàn toàn việc học tập của con người", "Giúp máy tính tự suy nghĩ thay con người", "Chỉ dùng để giải trí lúc rảnh rỗi"], x: "Thông tin đem lại hiểu biết cho con người, giúp con người có những lựa chọn tốt và đưa ra quyết định đúng đắn.", lv: 1 },
      { topic: "Thông tin và dữ liệu", type: "tf4", q: "Mỗi ý sau về vật mang tin đúng hay sai?", o: ["Tờ lịch treo tường là một vật mang tin.", "Cuốn sổ ghi chép bài học là một vật mang tin.", "Tiếng còi xe cứu thương là một vật mang tin.", "Đĩa CD ghi các bài hát là một vật mang tin."], a: [true, true, false, true], x: "a), b), d) Đúng: tờ lịch, cuốn sổ, đĩa CD đều lưu giữ thông tin, nên là vật mang tin. c) Sai: tiếng còi vang lên rồi mất, không phải một vật lưu giữ thông tin.", lv: 2 },
      { topic: "Xử lí thông tin", type: "match", q: "Nối mỗi thiết bị với chức năng của nó.", l: ["Micro", "Máy quét", "Máy chiếu", "Webcam"], r: ["Thu âm thanh để đưa vào máy tính", "Đưa chữ, hình ảnh trên giấy vào máy tính", "Chiếu hình ảnh từ máy tính lên màn lớn", "Thu hình ảnh, video để đưa vào máy tính", "Phát âm thanh từ máy tính ra ngoài"], x: "Micro thu âm thanh, webcam thu hình ảnh, máy quét chuyển nội dung trên giấy vào máy tính. Máy chiếu chiếu hình ảnh từ máy tính lên màn lớn.", lv: 1 },
      { topic: "Xử lí thông tin", type: "mc", q: "Ở con người, bộ phận nào giữ vai trò xử lí thông tin?", o: ["Bộ não", "Đôi mắt", "Đôi tai", "Làn da"], x: "Bộ não giữ vai trò xử lí thông tin. Mắt, tai, da là các giác quan giúp con người nhìn, nghe, cảm nhận thế giới xung quanh.", lv: 1 },
      { topic: "Thông tin trong máy tính", type: "mc", q: "Đơn vị nhỏ nhất dùng để đo dung lượng thông tin là:", o: ["Bit", "Byte", "Kilobyte (KB)", "Megabyte (MB)"], x: "Bit là đơn vị nhỏ nhất để đo dung lượng thông tin; 8 bit tạo thành 1 byte.", lv: 1 },
      { topic: "Thông tin trong máy tính", type: "mc", q: "Thiết bị lưu trữ nào sau đây có dung lượng lớn nhất?", o: ["Ổ đĩa cứng 1 TB", "Điện thoại có bộ nhớ 128 GB", "Thẻ nhớ 32 GB", "Đĩa CD 700 MB"], x: "1 TB = 1 024 GB, lớn hơn 128 GB và 32 GB; còn 700 MB chưa đến 1 GB. Vậy ổ đĩa cứng 1 TB có dung lượng lớn nhất.", lv: 2 },
      { topic: "Thông tin trong máy tính", type: "num", q: "Một tệp bài hát có dung lượng 1,5 MB. Dung lượng của tệp đó là bao nhiêu KB?", ans: 1536, unit: "KB", x: "1 MB = 1 024 KB, nên 1,5 MB = 1,5 × 1 024 = 1 536 (KB).", lv: 3 },
      { topic: "Thông tin trong máy tính", type: "num", q: "Ổ đĩa của máy tính còn trống 4 GB. Mỗi đoạn video có dung lượng 512 MB. Ổ đĩa chứa thêm được nhiều nhất bao nhiêu đoạn video như vậy?", ans: 8, unit: "đoạn", x: "4 GB = 4 × 1 024 MB = 4 096 MB. 4 096 : 512 = 8, nên ổ đĩa chứa thêm được 8 đoạn video.", lv: 3 },
      { topic: "Mạng máy tính", type: "mc", q: "Trường hợp nào sau đây là một mạng máy tính?", o: ["Ba máy tính được kết nối để truyền thông tin cho nhau", "Một máy tính để bàn chưa kết nối với thiết bị nào", "Một chiếc máy tính bỏ túi dùng để làm tính", "Một chiếc ti vi chưa kết nối mạng"], x: "Các máy tính được kết nối để truyền thông tin cho nhau tạo thành một mạng máy tính. Các trường hợp còn lại chỉ có một thiết bị đứng riêng.", lv: 1 },
      { topic: "Mạng máy tính", type: "tf4", q: "Mỗi ý sau về mạng máy tính đúng hay sai?", o: ["Trong mạng không dây, các thiết bị truyền thông tin cho nhau bằng sóng, không cần dây cáp.", "Máy tính xách tay có thể kết nối với mạng không dây.", "Mạng máy tính giúp các máy tính chạy nhanh hơn.", "Mạng máy tính chỉ dùng được khi các máy tính đặt trong cùng một phòng."], a: [true, true, false, false], x: "a), b) Đúng. c) Sai: nối mạng không làm từng máy tính chạy nhanh hơn. d) Sai: mạng có thể nối các máy tính ở nhiều phòng, nhiều tòa nhà khác nhau.", lv: 2 },
      { topic: "Mạng máy tính", type: "mc", q: "Khi các máy tính trong phòng học chưa nối mạng, muốn chuyển một tệp sang máy khác, các bạn phải chép tệp ra một thiết bị lưu trữ rồi mang sang. Khi các máy đã được nối mạng thì:", o: ["Có thể gửi tệp trực tiếp qua mạng sang máy khác", "Không chuyển được tệp sang máy khác nữa", "Phải in tệp ra giấy rồi gõ lại ở máy khác", "Phải tắt cả hai máy trước khi chuyển tệp"], x: "Nhờ mạng, các máy chia sẻ dữ liệu được với nhau: tệp được gửi trực tiếp qua mạng, không cần chép ra thiết bị lưu trữ rồi mang sang.", lv: 2 },
      { topic: "Internet", type: "mc", q: "Dùng Internet không hợp lí có thể gây ra tác hại nào?", o: ["Nghiện mạng, hại sức khỏe và việc học", "Tìm được nhiều tài liệu học tập bổ ích", "Liên lạc được với người thân ở nơi xa", "Đọc được tin tức mới một cách nhanh chóng"], x: "Dùng Internet quá nhiều dễ bị nghiện, thiếu ngủ, ít vận động, ảnh hưởng đến sức khỏe và việc học. Ba ý còn lại là lợi ích của Internet.", lv: 1 },
      { topic: "Internet", type: "match", q: "Nối mỗi dịch vụ trên Internet với công dụng của nó.", l: ["Thư điện tử", "Học trực tuyến", "Mua bán trực tuyến", "Hội thảo trực tuyến"], r: ["Gửi và nhận thư qua mạng", "Học bài, nghe thầy cô giảng qua mạng", "Đặt mua hàng và thanh toán qua mạng", "Họp, trao đổi có hình ảnh với nhiều người ở xa", "In tài liệu ra giấy"], x: "Thư điện tử để gửi, nhận thư; học trực tuyến để học qua mạng; mua bán trực tuyến để đặt mua hàng; hội thảo trực tuyến để họp, trao đổi với nhiều người ở xa. In tài liệu là việc của máy in, không phải dịch vụ trên Internet.", lv: 2 },
      { topic: "Mạng thông tin toàn cầu", type: "mc", q: "Đang xem trang web của một vườn quốc gia, Nam đưa con trỏ chuột vào dòng chữ “Các loài thú quý hiếm” thì con trỏ chuyển thành hình bàn tay. Nam nháy chuột vào dòng chữ đó thì:", o: ["Chuyển tới trang web hoặc vị trí mà liên kết đó trỏ đến", "Dòng chữ đó bị xóa khỏi trang web", "Trang web được in ngay ra giấy", "Chữ trên trang web tự động to gấp đôi"], x: "Con trỏ thành hình bàn tay cho biết dòng chữ là một liên kết (siêu liên kết). Nháy vào liên kết thì chuyển tới trang web hoặc vị trí trong trang mà liên kết đó trỏ đến; đi theo các liên kết như vậy gọi là duyệt web.", lv: 1 },
      { topic: "Mạng thông tin toàn cầu", type: "mc", q: "Đang đọc một bài trên các trang thông tin của bảo tàng, Vy muốn quay về trang giới thiệu chung, là trang mở ra đầu tiên khi truy cập địa chỉ của bảo tàng. Trang đó gọi là:", o: ["Trang chủ", "Thanh địa chỉ", "Siêu liên kết", "Thanh đánh dấu"], x: "Trang chủ là trang mở ra đầu tiên khi truy cập địa chỉ đó; địa chỉ truy cập chính là địa chỉ của trang chủ. Thanh địa chỉ, thanh đánh dấu là các phần của cửa sổ trình duyệt; siêu liên kết là chỗ nháy vào để chuyển trang, không phải một trang web.", lv: 1 },
      { topic: "Mạng thông tin toàn cầu", type: "mc", q: "Bạn biết địa chỉ website của trường và muốn xem bản tin mới nhất. Bạn làm thế nào?", o: ["Mở trình duyệt, gõ địa chỉ website rồi nhấn Enter", "Mở phần mềm soạn thảo văn bản rồi gõ địa chỉ vào", "Gửi thư điện tử hỏi nhà trường bản tin hôm nay", "Mở phần mềm vẽ để tìm bản tin"], x: "Trang web được mở bằng trình duyệt: gõ địa chỉ vào thanh địa chỉ của trình duyệt rồi nhấn Enter. Phần mềm soạn thảo, phần mềm vẽ không mở được trang web.", lv: 3 },
      { topic: "Tìm kiếm thông tin trên Internet", type: "order", q: "Sắp xếp các bước tìm kiếm thông tin trên Internet theo đúng thứ tự.", o: ["Mở trình duyệt web", "Truy cập trang tìm kiếm, ví dụ google.com.vn", "Gõ từ khóa vào ô tìm kiếm rồi nhấn Enter", "Xem danh sách kết quả, nháy vào kết quả phù hợp"], x: "Mở trình duyệt, vào trang tìm kiếm, gõ từ khóa; sau khi có danh sách kết quả thì chọn kết quả phù hợp để xem.", lv: 3 },
      { topic: "Tìm kiếm thông tin trên Internet", type: "mc", q: "Bạn tìm lịch thi học kì trên Internet và thấy nhiều kết quả khác nhau. Nên tin vào nguồn nào nhất?", o: ["Trang web chính thức của nhà trường", "Bài đăng của một tài khoản lạ trên mạng xã hội", "Tin nhắn chuyển tiếp không rõ ai viết", "Bình luận dưới một video giải trí"], x: "Không phải thông tin nào trên Internet cũng chính xác. Nên chọn nguồn chính thức, rõ ràng như trang web của nhà trường.", lv: 3 },
      { topic: "Thư điện tử", type: "mc", q: "Muốn đọc những thư người khác gửi cho mình, bạn mở mục nào trong hộp thư?", o: ["Hộp thư đến", "Thư nháp", "Thùng rác", "Danh bạ"], x: "Thư người khác gửi đến được lưu trong mục Hộp thư đến (Inbox).", lv: 1 },
      { topic: "Thư điện tử", type: "mc", q: "Bạn muốn xem lại nội dung bức thư mình đã gửi cho cô giáo hôm qua. Bạn mở mục nào trong hộp thư?", o: ["Thư đã gửi", "Thư nháp", "Thùng rác", "Danh bạ"], x: "Những thư mình đã gửi đi được lưu trong mục Thư đã gửi (Sent).", lv: 2 },
      { topic: "Thư điện tử", type: "tf4", q: "Mỗi ý sau về thư điện tử đúng hay sai?", o: ["Người nhận phải mở máy cùng lúc với người gửi thì mới nhận được thư.", "Mỗi địa chỉ thư điện tử là duy nhất, không trùng với địa chỉ của người khác.", "Có thể đọc thư điện tử trên máy tính hoặc điện thoại có kết nối Internet.", "Khi người nhận đọc xong, thư tự bị xóa khỏi hộp thư."], a: [false, true, true, false], x: "a) Sai: thư được lưu lại, người nhận mở máy lúc nào cũng đọc được. b), c) Đúng. d) Sai: thư vẫn còn cho đến khi người dùng tự xóa.", lv: 2 },
      { topic: "Thư điện tử", type: "order", q: "Sắp xếp các bước gửi một thư điện tử theo đúng thứ tự.", o: ["Đăng nhập vào hộp thư của mình", "Nháy nút Soạn thư", "Nhập địa chỉ người nhận, tiêu đề và nội dung thư", "Nháy nút Gửi"], x: "Phải đăng nhập hộp thư trước, rồi soạn thư mới, nhập địa chỉ người nhận, tiêu đề, nội dung và cuối cùng nháy Gửi.", lv: 3 },
      { topic: "An toàn thông tin trên Internet", type: "mc", q: "Dùng lời lẽ xúc phạm, đe dọa hoặc chế giễu người khác trên mạng được gọi là:", o: ["Bắt nạt trên mạng", "Trò chuyện trực tuyến", "Tìm kiếm thông tin", "Chia sẻ dữ liệu"], x: "Xúc phạm, đe dọa, chế giễu người khác qua mạng là bắt nạt trên mạng, có thể làm người bị bắt nạt rất buồn, sợ hãi.", lv: 1 },
      { topic: "An toàn thông tin trên Internet", type: "mc", q: "Vì sao cần cài phần mềm diệt virus và thường xuyên cập nhật phần mềm đó?", o: ["Để phát hiện, ngăn chặn cả những virus mới", "Để máy tính không cần kết nối Internet nữa", "Để máy tính tự soạn văn bản thay mình", "Để màn hình máy tính sáng hơn"], x: "Virus mới xuất hiện thường xuyên. Phần mềm diệt virus được cập nhật mới nhận ra được virus mới và bảo vệ dữ liệu trong máy.", lv: 2 },
      { topic: "An toàn thông tin trên Internet", type: "tf4", q: "Lan nhận được tin nhắn: “Chúc mừng bạn trúng thưởng một chiếc điện thoại! Hãy nháy vào đường link và nhập mật khẩu tài khoản để nhận quà.” Mỗi việc làm sau đúng hay sai?", o: ["Nháy ngay vào đường link để nhận quà.", "Không nhập mật khẩu, không gửi thông tin cá nhân.", "Báo cho bố mẹ hoặc thầy cô biết.", "Chuyển tin nhắn cho các bạn cùng lớp để các bạn cũng nhận quà."], a: [false, true, true, false], x: "Đây là tin nhắn lừa đảo để lấy mật khẩu, thông tin cá nhân. a), d) Sai: nháy vào link hay chuyển tiếp tin nhắn đều có thể làm bạn và các bạn khác bị lừa. b), c) Đúng.", lv: 3 }
    ]
  },

  /* ---------- Tin học 6 · Kiểm tra giữa học kì I (Kết nối tri thức) ----------
     Phạm vi nửa đầu học kì I, ghi ở note. Câu tự soạn. Mức độ lv của đề 1 ghi ở Phiên N25b (câu, chủ đề giữ nguyên; cách xếp mức
     như đề cuối kì I ở đầu file). Hai đề là kho của đề ngẫu nhiên "tin6-gk1-ngau-nhien" (không có câu riêng nên không ghi vào
     file này; ma trận ở data/banks/index.js). */
  "tin6-gk1-de1": {
    note: "Sách Kết nối tri thức, nửa đầu học kì I (Bài 1–5): thông tin và dữ liệu, xử lí thông tin, thông tin trong máy tính; mạng máy tính, Internet. Trường nào kiểm tra đến Bài 6 thì ôn thêm phần đó ở đề cuối kì I. Đề không có phần thực hành trên máy. Có lời giải từng câu.",
    questions: [
      { topic: "Thông tin và dữ liệu", type: "mc", q: "Đến đầu ngõ, Hoa thấy biển báo “Đường đang sửa, mời đi lối khác”, nên Hoa đạp xe theo đường vòng và vẫn đến lớp đúng giờ. Ví dụ này cho thấy thông tin giúp con người:", o: ["Có những lựa chọn tốt, đưa ra quyết định đúng đắn", "Thay đổi được con đường theo ý muốn", "Làm việc mà không cần suy nghĩ", "Không cần quan sát đường đi nữa"], x: "Thông tin đúng giúp con người có những lựa chọn tốt, giúp việc làm đạt hiệu quả. Biết đường đang sửa, Hoa chọn lối khác nên không bị kẹt lại, đến lớp đúng giờ.", lv: 2 },
      { topic: "Thông tin và dữ liệu", type: "mc", q: "Hết giờ ra chơi, tiếng trống trường vang lên. Thông tin học sinh nhận được từ tiếng trống là:", o: ["Đã hết giờ ra chơi, cần vào lớp", "Chiếc trống được làm bằng gỗ và da", "Bác bảo vệ là người đánh trống", "Trường có bao nhiêu chiếc trống"], x: "Tiếng trống là dữ liệu dạng âm thanh. Học sinh hiểu ý nghĩa của nó: đã hết giờ ra chơi, phải vào lớp. Hiểu biết đó là thông tin.", lv: 2 },
      { topic: "Thông tin và dữ liệu", type: "mc", q: "Bức ảnh in trên giấy, chiếc thẻ nhớ, quyển vở ghi bài có điểm chung là đều là:", o: ["Vật mang tin", "Thiết bị vào của máy tính", "Thiết bị kết nối mạng", "Bộ xử lí thông tin"], x: "Vật mang tin là phương tiện dùng để lưu trữ và truyền tải thông tin, ví dụ: giấy, sách vở, ảnh, USB, thẻ nhớ, đĩa CD.", lv: 2 },
      { topic: "Thông tin và dữ liệu", type: "mc", q: "Bình đo nhiệt độ cơ thể, thấy nhiệt kế chỉ 38,5 °C và biết mình đang bị sốt. Con số 38,5 °C là:", o: ["Dữ liệu", "Vật mang tin", "Thiết bị ra", "Bộ nhớ"], x: "Con số đọc được trên nhiệt kế là dữ liệu. Từ dữ liệu đó, Bình biết mình bị sốt: hiểu biết này là thông tin.", lv: 2 },
      { topic: "Thông tin và dữ liệu", type: "tf", q: "Thông tin chỉ có thể truyền từ người này sang người khác bằng lời nói.", a: false, x: "Sai. Thông tin có thể truyền bằng lời nói, chữ viết, hình ảnh, âm thanh, cử chỉ; qua sách báo, điện thoại, máy tính, Internet…", lv: 1 },
      { topic: "Xử lí thông tin", type: "mc", q: "Máy tính gồm bốn thành phần cơ bản để thực hiện các hoạt động xử lí thông tin. Đó là:", o: ["Thiết bị vào, bộ xử lí, thiết bị ra, bộ nhớ", "Bàn phím, chuột, loa, tai nghe", "Màn hình, máy in, máy quét, micro", "Chuột, bàn phím, USB, thẻ nhớ"], x: "Thiết bị vào thu nhận thông tin, bộ xử lí xử lí thông tin, thiết bị ra đưa thông tin ra ngoài, bộ nhớ lưu trữ thông tin.", lv: 1 },
      { topic: "Xử lí thông tin", type: "mc", q: "Thiết bị nào dưới đây là thiết bị ra của máy tính?", o: ["Loa", "Micro", "Bàn phím", "Máy quét"], x: "Loa phát âm thanh từ máy tính ra ngoài nên là thiết bị ra. Micro, bàn phím, máy quét đưa thông tin vào máy tính nên là thiết bị vào.", lv: 1 },
      { topic: "Xử lí thông tin", type: "mc", q: "Khi thu âm giọng đọc vào máy tính, micro giúp máy tính thực hiện hoạt động nào?", o: ["Thu nhận thông tin", "Xử lí thông tin", "Lưu trữ thông tin", "Truyền thông tin"], x: "Micro là thiết bị vào: nó thu nhận âm thanh để đưa vào máy tính.", lv: 2 },
      { topic: "Xử lí thông tin", type: "mc", q: "Lan ghi lời dặn của cô giáo vào sổ tay để khỏi quên. Việc ghi vào sổ tay là hoạt động:", o: ["Lưu trữ thông tin", "Thu nhận thông tin", "Xử lí thông tin", "Truyền thông tin"], x: "Nghe cô dặn là thu nhận thông tin; ghi lại vào sổ tay để dùng về sau là lưu trữ thông tin.", lv: 2 },
      { topic: "Xử lí thông tin", type: "mc", q: "Điểm mạnh nào sau đây là của máy tính?", o: ["Tính toán nhanh, chính xác, làm việc liên tục không mệt mỏi", "Tự suy nghĩ và tự đặt ra mục tiêu cho mình", "Hiểu được cảm xúc của con người", "Tự sửa chữa khi bị hỏng"], x: "Máy tính tính toán nhanh, chính xác, lưu trữ được rất nhiều dữ liệu và làm việc liên tục. Nhưng máy tính chỉ làm theo chỉ dẫn của con người, không tự suy nghĩ được.", lv: 1 },
      { topic: "Xử lí thông tin", type: "tf", q: "Máy in là thiết bị vào của máy tính.", a: false, x: "Sai. Máy in đưa kết quả từ máy tính ra giấy nên là thiết bị ra.", lv: 1 },
      { topic: "Thông tin trong máy tính", type: "mc", q: "Bit là:", o: ["Đơn vị nhỏ nhất dùng để biểu diễn thông tin trong máy tính", "Đơn vị đo dung lượng lớn nhất", "Tên một thiết bị lưu trữ", "Tên một phần mềm của máy tính"], x: "Trong máy tính, thông tin được biểu diễn bằng dãy bit. Bit là đơn vị nhỏ nhất, chỉ nhận một trong hai giá trị 0 hoặc 1.", lv: 1 },
      { topic: "Thông tin trong máy tính", type: "mc", q: "Dãy nào dưới đây là một dãy bit?", o: ["10110010", "10210010", "ABC01010", "1 2 3 4"], x: "Dãy bit chỉ gồm các kí hiệu 0 và 1. Dãy 10210010 có chữ số 2, dãy ABC01010 có chữ cái nên không phải dãy bit.", lv: 2 },
      { topic: "Thông tin trong máy tính", type: "fill", q: "Mỗi bit chỉ nhận một trong hai giá trị: 0 hoặc ___.", ans: ["1", "một"], x: "Bit nhận giá trị 0 hoặc 1. Máy tính biểu diễn chữ, số, hình ảnh, âm thanh… bằng các dãy bit.", lv: 1 },
      { topic: "Thông tin trong máy tính", type: "fill", q: "1 GB = ___ MB.", ans: ["1024", "1 024"], x: "1 GB = 1 024 MB (khoảng một nghìn MB). Tương tự, 1 MB = 1 024 KB và 1 KB = 1 024 byte.", lv: 1 },
      { topic: "Thông tin trong máy tính", type: "mc", q: "USB của Hà còn trống 2 GB. Mỗi bài hát có dung lượng khoảng 4 MB. USB chứa thêm được khoảng bao nhiêu bài hát?", o: ["Khoảng 500 bài", "Khoảng 50 bài", "Khoảng 8 bài", "Khoảng 5 000 bài"], x: "2 GB = 2 × 1 024 MB = 2 048 MB. 2 048 : 4 = 512, tức là khoảng 500 bài hát.", lv: 3 },
      { topic: "Thông tin trong máy tính", type: "mc", q: "Khả năng lưu trữ dữ liệu của một thiết bị nhớ được gọi là:", o: ["Dung lượng nhớ", "Tốc độ xử lí", "Vật mang tin", "Thiết bị ra"], x: "Dung lượng nhớ cho biết thiết bị chứa được bao nhiêu dữ liệu, đo bằng byte, KB, MB, GB, TB…", lv: 1 },
      { topic: "Mạng máy tính", type: "mc", q: "Các thành phần cơ bản của mạng máy tính là:", o: ["Thiết bị đầu cuối, thiết bị kết nối và phần mềm mạng", "Chỉ gồm các máy tính để bàn đặt trong cùng một phòng", "Màn hình, bàn phím và chuột", "Máy in, máy quét và loa"], x: "Mạng máy tính gồm: thiết bị đầu cuối (máy tính, điện thoại, máy in…), thiết bị kết nối (dây cáp mạng, bộ chia, bộ định tuyến…) và phần mềm mạng.", lv: 1 },
      { topic: "Mạng máy tính", type: "mc", q: "Thiết bị nào dưới đây là thiết bị đầu cuối trong mạng máy tính?", o: ["Máy tính xách tay", "Dây cáp mạng", "Bộ chia mạng (switch)", "Bộ định tuyến (router)"], x: "Máy tính xách tay là thiết bị đầu cuối, nơi người dùng gửi và nhận thông tin. Dây cáp mạng, bộ chia, bộ định tuyến là thiết bị kết nối.", lv: 2 },
      { topic: "Mạng máy tính", type: "fill", q: "Các thiết bị truyền thông tin cho nhau bằng sóng (như sóng wifi), không dùng dây cáp. Đó là mạng ___.", ans: ["không dây", "mạng không dây"], x: "Mạng truyền thông tin bằng sóng (như sóng wifi) là mạng không dây. Mạng dùng dây cáp để nối các thiết bị là mạng có dây.", lv: 1 },
      { topic: "Mạng máy tính", type: "mc", q: "Trong giờ học, cô giáo gửi tệp bài tập từ máy tính của cô đến máy tính của cả lớp qua mạng. Đây là lợi ích nào của mạng máy tính?", o: ["Chia sẻ dữ liệu", "Dùng chung máy in", "Làm máy tính chạy nhanh hơn", "Tăng dung lượng ổ cứng"], x: "Mạng máy tính giúp mọi người chia sẻ dữ liệu, trao đổi thông tin và dùng chung thiết bị như máy in. Ở đây cô giáo chia sẻ tệp bài tập.", lv: 2 },
      { topic: "Internet", type: "mc", q: "Nhà Bình vừa chuyển đến nhà mới, chưa có Internet. Để máy tính trong nhà truy cập được Internet, bố Bình cần đăng kí với:", o: ["Nhà cung cấp dịch vụ Internet (như VNPT, Viettel, FPT)", "Cửa hàng bán máy tính gần nhà", "Công ty sản xuất máy in", "Bưu điện để gửi thư"], x: "Máy tính kết nối với Internet thông qua một nhà cung cấp dịch vụ Internet. Ở nước ta có VNPT, Viettel, FPT…", lv: 1 },
      { topic: "Internet", type: "mc", q: "Qua Internet, các bạn có thể trò chuyện, bình luận và cùng làm một bài tập với nhau. Đây là đặc điểm nào của Internet?", o: ["Tính tương tác", "Tính không chủ sở hữu", "Tính toàn cầu", "Tính dễ tiếp cận"], x: "Tính tương tác: Internet cho phép mọi người giao tiếp, trao đổi, cộng tác với nhau. Tính toàn cầu là kết nối khắp thế giới; tính dễ tiếp cận là truy cập được ở bất cứ đâu, bất cứ lúc nào; tính không chủ sở hữu là không ai sở hữu Internet.", lv: 2 },
      { topic: "Internet", type: "tf", q: "Từ một máy tính ở Việt Nam, không thể xem trang web của một trường học ở Nhật Bản qua Internet.", a: false, x: "Sai. Internet liên kết các mạng máy tính trên khắp thế giới, nên từ Việt Nam vẫn xem được trang web của một trường học ở Nhật Bản.", lv: 1 },
      { topic: "Internet", type: "tf", q: "Nhờ Internet, học sinh có thể học trực tuyến, tìm tài liệu và trao đổi bài với bạn ở xa.", a: true, x: "Đúng. Internet cung cấp nguồn thông tin rất lớn và nhiều dịch vụ: học tập, tin tức, giải trí, thư điện tử, trò chuyện…", lv: 1 }
    ]
  },
  /* Đề 2 (Phiên N25b): cùng phạm vi Bài 1–5, đủ 5 chủ đề của đề 1 (chữ chủ đề giữ nguyên), chia đúng theo ma trận của đề ngẫu
     nhiên "tin6-gk1-ngau-nhien" (10 Biết, 8 Hiểu, 7 Vận dụng; ma trận ở data/banks/index.js). Đề 1 có 14 – 10 – 1 nên Đề 2 bù
     các ô Vận dụng (tìm nguồn thông tin, sắp xếp các hoạt động xử lí thông tin, chụp và gửi ảnh, đổi byte sang KB, chỗ trống trên
     điện thoại, dùng chung máy in qua mạng, dùng Internet hợp lí). Hai đề là kho của đề ngẫu nhiên (không có câu riêng); lời giải
     của đề 1 liệt kê vai trò bốn thành phần của máy tính, ví dụ thiết bị vào, ra, thiết bị đầu cuối, kết nối, lợi ích của mạng,
     nên Đề 2 không hỏi lại các điều đó (Rút ra N25). Cách xếp mức như đề cuối kì I (đầu file). */
  "tin6-gk1-de2": {
    note: "Sách Kết nối tri thức, nửa đầu học kì I (Bài 1–5): thông tin và dữ liệu, xử lí thông tin, thông tin trong máy tính; mạng máy tính, Internet. Trường nào kiểm tra đến Bài 6 thì ôn thêm phần đó ở đề cuối kì I. Đề không có phần thực hành trên máy. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Có lời giải từng câu.",
    questions: [
      { topic: "Thông tin và dữ liệu", type: "mc", q: "Con người thu nhận thông tin từ thế giới xung quanh chủ yếu nhờ:", o: ["Các giác quan: mắt nhìn, tai nghe, mũi ngửi, lưỡi nếm, da sờ", "Chỉ nhờ đôi mắt", "Chỉ nhờ máy tính", "Chỉ nhờ sách vở"], x: "Con người thu nhận thông tin qua các giác quan: nhìn, nghe, ngửi, nếm, sờ. Máy tính, sách vở chỉ là phương tiện mang thông tin đến cho các giác quan.", lv: 1 },
      { topic: "Thông tin và dữ liệu", type: "mc", q: "Vật nào dưới đây KHÔNG phải là vật mang tin?", o: ["Chiếc bút chì", "Tấm bản đồ", "Đĩa CD", "Tờ báo"], x: "Tấm bản đồ, đĩa CD, tờ báo đều chứa thông tin để người khác đọc, nghe được. Bút chì chỉ là dụng cụ để viết, không chứa thông tin.", lv: 1 },
      { topic: "Thông tin và dữ liệu", type: "mc", q: "Cùng nhìn một bức ảnh chụp bầu trời đầy mây đen, Lan nghĩ “sắp mưa rồi”, còn Nam nghĩ “chiều nay trời sẽ mát”. Điều này cho thấy:", o: ["Từ cùng một dữ liệu, mỗi người có thể rút ra thông tin khác nhau", "Bức ảnh không phải là dữ liệu", "Chỉ có một trong hai bạn nhận được thông tin", "Thông tin không liên quan gì đến dữ liệu"], x: "Bức ảnh là dữ liệu; mỗi người xử lí dữ liệu đó theo hiểu biết, kinh nghiệm của mình nên rút ra thông tin khác nhau.", lv: 2 },
      { topic: "Thông tin và dữ liệu", type: "tf4", q: "Mỗi ý sau về thông tin và dữ liệu đúng hay sai?", o: ["Dữ liệu được ghi lại trên các vật mang tin.", "Dữ liệu chỉ có thể là các con số.", "Thông tin chỉ có trong máy tính.", "Một bức ảnh chụp bằng điện thoại cũng là dữ liệu."], a: [true, false, false, true], x: "a), d) Đúng. b) Sai: dữ liệu có thể là chữ, số, hình ảnh, âm thanh. c) Sai: thông tin có ở khắp nơi trong đời sống, từ lời nói, sách báo, biển báo… không chỉ trong máy tính.", lv: 2 },
      { topic: "Thông tin và dữ liệu", type: "mc", q: "Mai muốn đến hiệu sách gần nhà vào Chủ nhật nhưng không biết hiệu sách có mở cửa hôm đó không. Mai nên làm gì để có thông tin đáng tin cậy nhất?", o: ["Xem giờ mở cửa ghi trên biển hiệu hoặc trang web của hiệu sách", "Đoán là có mở, rồi đi thử", "Hỏi một người bạn chưa từng đến hiệu sách", "Đợi đến thứ Hai rồi đi"], x: "Thông tin đáng tin cậy nhất đến từ chính hiệu sách (biển hiệu, trang web). Đoán mò hay hỏi người không biết có thể cho thông tin sai.", lv: 3 },
      { topic: "Xử lí thông tin", type: "mc", q: "Máy chiếu (dùng để chiếu bài giảng từ máy tính lên màn lớn) là:", o: ["Thiết bị ra", "Thiết bị vào", "Bộ xử lí", "Bộ nhớ"], x: "Máy chiếu đưa hình ảnh từ máy tính ra ngoài cho mọi người xem, nên là thiết bị ra.", lv: 1 },
      { topic: "Xử lí thông tin", type: "mc", q: "Hoạt động truyền thông tin là:", o: ["Đưa thông tin từ nơi này đến nơi khác, từ người này đến người khác", "Ghi thông tin lại để dùng về sau", "Suy nghĩ, tính toán để tạo ra thông tin mới", "Tiếp nhận thông tin từ bên ngoài qua các giác quan"], x: "Truyền thông tin là đưa thông tin từ người này đến người khác, từ nơi này đến nơi khác, ví dụ gọi điện, gửi thư, phát thanh.", lv: 1 },
      { topic: "Xử lí thông tin", type: "mc", q: "Nam đọc bảng thông báo lịch thi, nhẩm tính xem còn mấy ngày nữa đến ngày thi, rồi ghi ngày thi vào sổ tay. Hoạt động nào là xử lí thông tin?", o: ["Nhẩm tính xem còn mấy ngày nữa", "Đọc bảng thông báo", "Ghi ngày thi vào sổ tay", "Cả ba hoạt động"], x: "Suy nghĩ, tính toán từ thông tin đã có để ra kết quả mới là xử lí thông tin. Đọc bảng là thu nhận, ghi vào sổ là lưu trữ thông tin.", lv: 2 },
      { topic: "Xử lí thông tin", type: "tf4", q: "Mỗi ý sau về xử lí thông tin đúng hay sai?", o: ["Con người có thể xử lí thông tin mà không cần máy tính.", "Máy tính có thể tự đặt ra mục tiêu và tự quyết định mọi việc.", "Máy tính lưu trữ được lượng dữ liệu rất lớn và tìm lại rất nhanh.", "Chuột máy tính là một thiết bị vào."], a: [true, false, true, true], x: "a), c), d) Đúng. b) Sai: máy tính chỉ làm theo chỉ dẫn của con người, không tự đặt mục tiêu hay tự quyết định.", lv: 2 },
      { topic: "Xử lí thông tin", type: "order", q: "Sắp xếp các hoạt động của Lan khi làm bài tập về nhà theo đúng thứ tự diễn ra.", o: ["Đọc đề bài trong sách", "Suy nghĩ tìm cách giải", "Viết lời giải vào vở", "Đưa vở cho cô giáo chấm"], x: "Đọc đề (thu nhận) → suy nghĩ (xử lí) → viết vào vở (lưu trữ) → đưa cô chấm (truyền thông tin).", lv: 3 },
      { topic: "Xử lí thông tin", type: "mc", q: "An dùng điện thoại chụp ảnh bảng ghi bài tập về nhà, ảnh được lưu trong điện thoại, rồi An gửi ảnh cho Bình đang ốm ở nhà. Ba hoạt động xử lí thông tin ở đây lần lượt là:", o: ["Thu nhận, lưu trữ, truyền thông tin", "Xử lí, truyền, thu nhận thông tin", "Lưu trữ, thu nhận, xử lí thông tin", "Truyền, lưu trữ, xử lí thông tin"], x: "Chụp ảnh là thu nhận thông tin, lưu ảnh trong điện thoại là lưu trữ, gửi ảnh cho Bình là truyền thông tin.", lv: 3 },
      { topic: "Thông tin trong máy tính", type: "num", q: "Dãy bit 11001010 gồm bao nhiêu bit?", ans: 8, unit: "bit", x: "Mỗi kí hiệu 0 hoặc 1 là một bit. Dãy 11001010 có 8 kí hiệu nên gồm 8 bit.", lv: 1 },
      { topic: "Thông tin trong máy tính", type: "mc", q: "Đơn vị nào dưới đây dùng để đo dung lượng thông tin?", o: ["Megabyte (MB)", "Mét (m)", "Kilôgam (kg)", "Giây (s)"], x: "Dung lượng thông tin đo bằng byte và các bội của nó: KB, MB, GB, TB. Mét đo chiều dài, kilôgam đo khối lượng, giây đo thời gian.", lv: 1 },
      { topic: "Thông tin trong máy tính", type: "mc", q: "Phát biểu nào sau đây đúng?", o: ["1 MB lớn hơn 1 KB", "1 KB lớn hơn 1 GB", "1 byte lớn hơn 1 MB", "1 bit lớn hơn 1 byte"], x: "Thứ tự từ nhỏ đến lớn: bit, byte, KB, MB, GB, TB. Vì vậy 1 MB lớn hơn 1 KB.", lv: 2 },
      { topic: "Thông tin trong máy tính", type: "tf4", q: "Mỗi ý sau về thông tin trong máy tính đúng hay sai?", o: ["Chữ, hình ảnh, âm thanh đều được máy tính lưu dưới dạng dãy bit.", "Một tệp ảnh thường có dung lượng lớn hơn một tệp văn bản ngắn.", "Dãy bit 1010 và dãy bit 0101 biểu diễn cùng một thông tin.", "Thẻ nhớ, USB, ổ đĩa cứng là các thiết bị lưu trữ dữ liệu."], a: [true, true, false, true], x: "a), b), d) Đúng. c) Sai: hai dãy bit khác nhau biểu diễn hai thông tin khác nhau.", lv: 2 },
      { topic: "Thông tin trong máy tính", type: "num", q: "Một tệp văn bản có dung lượng 4 096 byte. Dung lượng đó bằng bao nhiêu KB?", ans: 4, unit: "KB", x: "1 KB = 1 024 byte, nên 4 096 byte = 4 096 : 1 024 = 4 (KB).", lv: 3 },
      { topic: "Thông tin trong máy tính", type: "mc", q: "Điện thoại của Mai còn trống 1 GB. Mai muốn chép 6 đoạn phim, mỗi đoạn 200 MB. Điện thoại có đủ chỗ không?", o: ["Không, vì 6 đoạn phim cần 1 200 MB, nhiều hơn 1 024 MB còn trống", "Có, vì 1 GB lớn hơn 200 MB", "Có, vì 6 đoạn phim chỉ cần 600 MB", "Không, vì điện thoại không chép được phim"], x: "6 đoạn phim cần 6 × 200 = 1 200 MB. Chỗ trống 1 GB = 1 024 MB, ít hơn 1 200 MB nên không đủ.", lv: 3 },
      { topic: "Mạng máy tính", type: "mc", q: "Vai trò của thiết bị kết nối trong mạng máy tính là:", o: ["Nối các thiết bị đầu cuối với nhau để truyền tín hiệu giữa chúng", "Hiển thị hình ảnh cho người dùng xem", "Lưu trữ bài tập của học sinh", "In tài liệu ra giấy"], x: "Thiết bị kết nối (dây cáp, bộ chia, bộ định tuyến…) nối các thiết bị đầu cuối lại với nhau và truyền tín hiệu giữa chúng.", lv: 1 },
      { topic: "Mạng máy tính", type: "mc", q: "Phần mềm mạng là:", o: ["Chương trình giúp các thiết bị trong mạng giao tiếp, truyền và nhận thông tin với nhau", "Sợi dây cáp nối các máy tính", "Chiếc máy tính mạnh nhất trong mạng", "Trò chơi cài sẵn trên máy tính"], x: "Phần mềm mạng được cài trên các thiết bị để chúng giao tiếp được với nhau, truyền và nhận thông tin đúng cách. Dây cáp là thiết bị kết nối, máy tính là thiết bị đầu cuối.", lv: 1 },
      { topic: "Mạng máy tính", type: "tf4", q: "Mỗi ý sau về mạng máy tính đúng hay sai?", o: ["Mạng máy tính có thể gồm cả máy tính và điện thoại thông minh.", "Hai máy tính nối với nhau bằng một sợi dây cáp cũng là một mạng máy tính.", "Muốn chuyển tệp giữa hai máy tính trong cùng một mạng, phải chép tệp ra USB rồi mang sang.", "Mạng máy tính chỉ dùng được ở trường học."], a: [true, true, false, false], x: "a), b) Đúng. c) Sai: các máy trong cùng một mạng gửi tệp cho nhau qua mạng, không cần USB. d) Sai: mạng máy tính có ở gia đình, cơ quan, cửa hàng…", lv: 2 },
      { topic: "Mạng máy tính", type: "mc", q: "Nhà Hùng mua một máy in. Hùng muốn máy tính của bố và máy tính của mình đều in được mà không phải cắm máy in qua lại. Cách làm hợp lí là:", o: ["Nối máy in vào mạng của gia đình để cả hai máy tính đều in được qua mạng", "Mua thêm một máy in nữa cho mỗi máy tính", "Mỗi lần in lại tháo máy in cắm sang máy kia", "Không in nữa, chép ra giấy bằng tay"], x: "Khi máy in được nối vào mạng gia đình, mọi máy tính trong mạng đều gửi lệnh in được, không cần cắm trực tiếp.", lv: 3 },
      { topic: "Internet", type: "mc", q: "Hoạt động nào dưới đây KHÔNG dùng đến Internet?", o: ["Gửi một bức thư viết tay qua bưu điện", "Gửi thư điện tử cho bạn", "Học trực tuyến với thầy cô", "Xem phim trực tuyến"], x: "Thư điện tử, học trực tuyến, xem phim trực tuyến đều cần Internet. Thư viết tay gửi qua bưu điện không cần Internet.", lv: 1 },
      { topic: "Internet", type: "mc", q: "Em có thể truy cập Internet bằng thiết bị nào?", o: ["Máy tính, điện thoại thông minh, máy tính bảng có kết nối mạng", "Chỉ máy tính để bàn", "Chỉ điện thoại thông minh", "Mọi thiết bị, kể cả khi không kết nối mạng"], x: "Nhiều loại thiết bị truy cập được Internet: máy tính, điện thoại thông minh, máy tính bảng, ti vi thông minh… miễn là có kết nối mạng.", lv: 1 },
      { topic: "Internet", type: "mc", q: "Một bạn ở Việt Nam và một bạn ở Pháp cùng chơi một trò chơi trực tuyến và trò chuyện với nhau. Tình huống này thể hiện những đặc điểm nào của Internet?", o: ["Tính toàn cầu và tính tương tác", "Tính không chủ sở hữu", "Tính dễ tiếp cận và tính có chủ sở hữu", "Không thể hiện đặc điểm nào"], x: "Hai bạn ở hai nước kết nối được với nhau: tính toàn cầu. Hai bạn cùng chơi, trò chuyện, trao đổi với nhau: tính tương tác.", lv: 2 },
      { topic: "Internet", type: "mc", q: "Bà của Hoa sống ở quê, muốn mỗi tuần được nhìn thấy và trò chuyện với Hoa đang học ở thành phố. Cách dùng Internet nào phù hợp nhất?", o: ["Gọi video qua Internet với bà vào cuối tuần", "Gửi thư điện tử cho bà mỗi tháng một lần", "Đăng ảnh lên mạng xã hội, không nhắn gì cho bà", "Tìm trên mạng thông tin về quê của bà"], x: "Gọi video qua Internet giúp hai bà cháu vừa nhìn thấy nhau, vừa trò chuyện ngay lúc đó dù ở xa. Thư điện tử gửi mỗi tháng một lần thì không nhìn thấy nhau; đăng ảnh hay tìm thông tin trên mạng thì không trò chuyện được với bà.", lv: 3 },
    ]
  },
  /* ---------- Tin học 6 · Kiểm tra giữa học kì II (Kết nối tri thức) ----------
     Phạm vi nửa đầu học kì II ghi ở note (Bài 9–13; Bài 14 thực hành tổng hợp không ra câu). Câu tự soạn, mức độ lv ở từng câu
     (Phiên N12b). Hai đề là kho của đề ngẫu nhiên "tin6-gk2-ngau-nhien" (không có câu riêng nên không ghi vào file này; ma trận ở
     data/banks/index.js); hai đề cùng phân bố chủ đề và mức như ma trận, nên ô nào cũng có gấp đôi số câu ô đó rút. Bài 9 có cả
     trong đề cuối kì I (tin6-ck1): câu ở đây soạn mới, không trùng ý với câu ở đó (tests/kiem-tra-de.js so trùng chữ trong mọi
     đề). Cách xếp mức: nêu khái niệm, thành phần, tên lệnh, nhóm lệnh, đơn vị là Biết; phân biệt định dạng kí tự, đoạn, trang,
     giải thích vì sao, đọc sơ đồ, đọc bảng trong hình, nhận xét một ý là Hiểu; sắp xếp các bước làm, chọn cách làm cho một tình
     huống, tính số hàng cần có là Vận dụng. Câu ở hai ô khác nhau, cả hai câu của một ô, có thể cùng được rút vào một đề, nên đề
     bài, các lựa chọn, lời giải không ghi sẵn đáp án của câu khác: tên lệnh, nhóm lệnh chỉ hỏi ở một câu trong cả kho (câu sắp
     xếp các bước ghi việc làm, không ghi tên lệnh). Hình sơ đồ tư duy: chủ đề chính là hình bầu dục tô sun-soft ở giữa, chủ đề
     nhánh là hình chữ nhật tô acc-soft nối với chủ đề chính bằng đường kẻ, chi tiết là chữ nhỏ cạnh nhánh; hình bảng vẽ bằng
     đường kẻ dọc, ngang (tests/tin-congnghe6-gk2.js đọc lại hai hình). */
  "tin6-gk2-de1": {
    note: "Sách Kết nối tri thức, nửa đầu học kì II: Bài 9 An toàn thông tin trên Internet; Bài 10 Sơ đồ tư duy; Bài 11 Định dạng văn bản; Bài 12 Trình bày thông tin ở dạng bảng; Bài 13 Thực hành: Tìm kiếm và thay thế. Có trường dạy Bài 9 ở học kì I, phụ huynh đối chiếu với đề cương của trường. Đề không có phần thực hành trên máy. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Có lời giải từng câu.",
    questions: [
      { topic: "An toàn thông tin trên Internet", type: "mc", q: "Phần mềm độc hại (mã độc) dễ xâm nhập vào máy tính khi em:", o: ["Mở tệp đính kèm hoặc đường link lạ nhận được trên mạng", "Tắt máy tính đúng cách sau khi dùng", "Chỉ truy cập các trang web của trường và của nhà xuất bản", "Cập nhật phần mềm diệt virus"], x: "Tệp đính kèm, đường link lạ (trong thư, tin nhắn, quảng cáo) thường chứa mã độc. Không mở chúng, chỉ vào trang web tin cậy và cập nhật phần mềm diệt virus giúp máy tính an toàn hơn.", lv: 1 },
      { topic: "An toàn thông tin trên Internet", type: "tf4", q: "Mỗi ý sau về nguy cơ khi dùng Internet đúng hay sai?", o: ["Dùng Internet quá nhiều có thể gây nghiện, ảnh hưởng đến việc học và sức khỏe.", "Mọi thông tin trên Internet đều đúng vì đã được kiểm duyệt trước khi đăng.", "Người lạ trên mạng có thể giả làm bạn cùng tuổi để làm quen và lừa gạt.", "Máy tính không nối mạng vẫn có thể bị lây mã độc qua USB."], a: [true, false, true, true], x: "a), c), d) Đúng: nghiện Internet, bị lừa gạt, nhiễm mã độc (kể cả qua USB) là những nguy cơ thường gặp. b) Sai: ai cũng có thể đăng thông tin lên Internet, nên có nhiều tin sai, tin giả; cần kiểm tra ở nguồn tin cậy.", lv: 2 },
      { topic: "An toàn thông tin trên Internet", type: "mc", q: "Hà thấy trên mạng một bài viết “Uống nước lá X chữa khỏi mọi bệnh” được rất nhiều người chia sẻ. Hà nên làm gì?", o: ["Kiểm tra ở nguồn tin cậy, hỏi bố mẹ hoặc thầy cô trước khi tin và chia sẻ", "Chia sẻ ngay cho bạn bè vì nhiều người đã chia sẻ thì chắc là đúng", "Làm theo ngay để thử xem có đúng không", "Bình luận chửi người đăng vì chắc chắn là tin giả"], x: "Số người chia sẻ không chứng tỏ thông tin đúng. Với thông tin về sức khỏe, cần kiểm tra ở nguồn tin cậy (cơ quan y tế, báo chính thống) và hỏi người lớn trước khi tin hay chia sẻ; không làm theo và cũng không xúc phạm người khác trên mạng.", lv: 3 },
      { topic: "Sơ đồ tư duy", type: "mc", q: "Cách ghi chép nào dưới đây là một sơ đồ tư duy?", o: ["Các ý viết ngắn gọn, nối với nhau bằng các đường nối, có thêm hình ảnh, màu sắc", "Một đoạn văn chép lại phần ghi nhớ của bài", "Một bảng gồm các hàng và cột ghi kết quả khảo sát", "Danh sách các ý đánh số 1, 2, 3 từ trên xuống dưới"], x: "Sơ đồ tư duy trình bày thông tin trực quan bằng chữ ngắn gọn (từ khóa), hình ảnh và các đường nối cho thấy ý nào thuộc ý nào. Đoạn văn, bảng, danh sách đánh số là những cách ghi chép khác.", lv: 1 },
      { topic: "Sơ đồ tư duy", type: "mc", q: "Các thành phần của một sơ đồ tư duy gồm:", o: ["Chủ đề chính, các chủ đề nhánh và các chi tiết của từng nhánh", "Tiêu đề, phần mở bài, phần thân bài và phần kết bài", "Hàng, cột và ô", "Trang bìa, mục lục và các chương"], x: "Sơ đồ tư duy có chủ đề chính, từ đó tỏa ra các chủ đề nhánh; mỗi chủ đề nhánh có các chi tiết (ý nhỏ hơn) của nó.", lv: 1 },
      { topic: "Sơ đồ tư duy", type: "tf4", q: "Mỗi ý sau về sơ đồ tư duy đúng hay sai?", o: ["Sơ đồ tư duy giúp nhìn thấy mối liên hệ giữa các ý.", "Sơ đồ tư duy chỉ tạo được trên máy tính.", "Có thể thêm hình ảnh vào sơ đồ tư duy.", "Một chủ đề nhánh có thể có nhiều chi tiết."], a: [true, false, true, true], x: "a), c), d) Đúng: các đường nối cho thấy ý nào thuộc ý nào; sơ đồ có thể có hình ảnh; mỗi nhánh có thể có nhiều ý nhỏ. b) Sai: có thể vẽ sơ đồ tư duy trên giấy.", lv: 2 },
      { topic: "Sơ đồ tư duy", type: "mc", q: "Trong sơ đồ tư duy ở hình, chủ đề chính là:", svg: '<svg viewBox="0 0 320 200"><line x1="160" y1="100" x2="62" y2="40"/><line x1="160" y1="100" x2="258" y2="40"/><line x1="160" y1="100" x2="160" y2="156"/><ellipse cx="160" cy="100" rx="46" ry="22" fill="sun-soft"/><text x="160" y="105" text-anchor="middle" font-size="15" fill="ink">Nhà ở</text><rect x="20" y="24" width="84" height="32" rx="6" fill="acc-soft"/><text x="62" y="45" text-anchor="middle" font-size="14" fill="ink">Vai trò</text><rect x="216" y="24" width="84" height="32" rx="6" fill="acc-soft"/><text x="258" y="45" text-anchor="middle" font-size="14" fill="ink">Cấu tạo</text><rect x="118" y="140" width="84" height="32" rx="6" fill="acc-soft"/><text x="160" y="161" text-anchor="middle" font-size="14" fill="ink">Kiểu nhà</text><text x="62" y="76" text-anchor="middle" font-size="13" fill="muted">che mưa, nắng</text><text x="258" y="76" text-anchor="middle" font-size="13" fill="muted">móng, thân, mái</text><text x="160" y="192" text-anchor="middle" font-size="13" fill="muted">nhà sàn, chung cư</text></svg>', o: ["Nhà ở", "Vai trò", "Kiểu nhà", "Móng, thân, mái"], x: "Chủ đề chính được đặt ở giữa sơ đồ (ô “Nhà ở”); “Vai trò”, “Cấu tạo”, “Kiểu nhà” là ba chủ đề nhánh nối với chủ đề chính; “móng, thân, mái” là chi tiết của nhánh “Cấu tạo”.", lv: 2 },
      { topic: "Sơ đồ tư duy", type: "order", q: "Nhóm của Tú vẽ sơ đồ tư duy “Chuyến tham quan” trên một tờ giấy to. Sắp xếp các việc theo đúng thứ tự.", o: ["Viết “Chuyến tham quan” ở giữa tờ giấy và khoanh lại", "Vẽ các nhánh “Thời gian”, “Địa điểm”, “Chuẩn bị” tỏa ra từ đó", "Ghi dưới nhánh “Chuẩn bị” các ý: nước uống, mũ, sổ ghi chép"], x: "Vẽ sơ đồ tư duy đi từ chủ đề chính ở giữa tờ giấy, rồi các chủ đề nhánh tỏa ra từ chủ đề chính, cuối cùng ghi chi tiết cho từng nhánh bằng từ khóa ngắn. Có thể thêm hình ảnh, màu sắc cho dễ nhớ.", lv: 3 },
      { topic: "Định dạng văn bản", type: "mc", q: "Định dạng văn bản là:", o: ["Thay đổi cách trình bày của văn bản để văn bản đẹp, rõ ràng, dễ đọc", "Gõ nội dung văn bản vào máy tính", "Lưu văn bản vào ổ đĩa", "Gửi văn bản qua thư điện tử"], x: "Định dạng văn bản là thay đổi kiểu dáng, vị trí của chữ, của đoạn, của trang để văn bản đẹp và dễ đọc hơn; nội dung văn bản không đổi.", lv: 1 },
      { topic: "Định dạng văn bản", type: "mc", q: "Định dạng kí tự là thay đổi:", o: ["Phông chữ, cỡ chữ, kiểu chữ, màu chữ", "Hướng trang và lề trang", "Khoảng cách giữa các dòng và căn lề đoạn", "Số hàng, số cột của bảng"], x: "Định dạng kí tự tác động lên từng chữ: phông chữ, cỡ chữ, kiểu chữ (đậm, nghiêng, gạch chân), màu chữ. Hướng trang, lề trang thuộc định dạng trang; khoảng cách dòng, căn lề thuộc định dạng đoạn.", lv: 1 },
      { topic: "Định dạng văn bản", type: "fill", q: "Khổ giấy thường dùng để in văn bản ở nước ta là khổ ___.", ans: ["A4", "a4"], x: "Khổ giấy A4 (21 cm × 29,7 cm) là khổ giấy phổ biến nhất khi in văn bản.", lv: 1 },
      { topic: "Định dạng văn bản", type: "tf4", q: "Mỗi ý sau về định dạng văn bản đúng hay sai?", o: ["Chọn khối văn bản trước khi định dạng thì định dạng chỉ áp dụng cho phần được chọn.", "Sau khi định dạng, nội dung chữ của văn bản bị thay đổi.", "Có thể định dạng lại nhiều lần cho đến khi vừa ý.", "Phải in văn bản ra giấy rồi mới định dạng được."], a: [true, false, true, false], x: "a), c) Đúng: định dạng áp dụng cho phần văn bản đang được chọn và làm lại được bao nhiêu lần cũng được. b) Sai: định dạng chỉ đổi cách trình bày, chữ trong văn bản giữ nguyên. d) Sai: định dạng làm trên máy, trước khi in.", lv: 2 },
      { topic: "Định dạng văn bản", type: "mc", q: "Trong phần mềm soạn thảo, một đoạn văn bản được tính:", o: ["Từ sau một lần nhấn phím Enter đến lần nhấn Enter tiếp theo", "Từ đầu dòng đến hết dòng đó trên màn hình", "Từ chữ hoa đầu câu đến dấu chấm", "Từ đầu trang đến cuối trang"], x: "Nhấn Enter là kết thúc một đoạn và bắt đầu đoạn mới. Một đoạn có thể gồm nhiều dòng, nhiều câu; một dòng trên màn hình không phải là một đoạn.", lv: 2 },
      { topic: "Định dạng văn bản", type: "mc", q: "Đoạn văn bản được căn thẳng hai lề (căn đều) có đặc điểm:", o: ["Các dòng (trừ dòng cuối) thẳng đều ở cả lề trái và lề phải", "Mọi dòng đều được đặt vào chính giữa trang", "Chỉ lề trái thẳng, lề phải lởm chởm", "Chữ ở mọi dòng đều in đậm"], x: "Căn thẳng hai lề giãn khoảng cách giữa các từ để mỗi dòng (trừ dòng cuối đoạn) chạm cả lề trái và lề phải. Căn trái chỉ thẳng lề trái; căn giữa đặt dòng vào giữa.", lv: 2 },
      { topic: "Định dạng văn bản", type: "order", q: "Sắp xếp các bước in một văn bản theo đúng thứ tự.", o: ["Mở văn bản cần in và kiểm tra lại cách trình bày", "Chọn lệnh in", "Chọn máy in và số bản cần in", "Nháy nút in để máy in bắt đầu in"], x: "Trước khi in cần xem lại văn bản (định dạng trang, lỗi chính tả), rồi mới chọn lệnh in, chọn máy in, số bản và ra lệnh in để khỏi in hỏng, tốn giấy.", lv: 3 },
      { topic: "Định dạng văn bản", type: "mc", q: "Tiêu đề của tờ báo tường cần nổi bật hơn phần bài viết. Cách định dạng tiêu đề phù hợp là:", o: ["In đậm, chọn cỡ chữ to hơn phần bài viết và căn giữa", "Chọn cỡ chữ nhỏ hơn phần bài viết cho gọn", "Giữ nguyên như phần bài viết để thống nhất", "Gạch chân từng chữ và dùng cỡ chữ thật nhỏ"], x: "Tiêu đề thường in đậm, cỡ chữ to hơn và căn giữa để người đọc nhìn thấy đầu tiên. Chữ nhỏ hơn hay giống hệt bài viết thì tiêu đề không nổi bật.", lv: 3 },
      { topic: "Trình bày thông tin ở dạng bảng", type: "mc", q: "Trình bày thông tin ở dạng bảng giúp:", o: ["Thông tin được sắp xếp theo hàng, cột nên dễ so sánh, dễ tra cứu", "Văn bản chứa được nhiều thông tin hơn", "Máy tính xử lí thông tin nhanh hơn", "Người đọc không cần đọc thông tin"], x: "Bảng xếp thông tin cùng loại vào cùng cột, cùng đối tượng vào cùng hàng, nên nhìn là thấy ngay, dễ so sánh và tìm kiếm, ví dụ thời khóa biểu, bảng điểm.", lv: 1 },
      { topic: "Trình bày thông tin ở dạng bảng", type: "mc", q: "Trong bảng, phần giao nhau của một hàng và một cột được gọi là:", o: ["Ô", "Trang", "Đoạn", "Dòng kẻ"], x: "Bảng gồm các hàng và các cột; mỗi hàng và mỗi cột giao nhau tạo thành một ô, nội dung được nhập vào các ô.", lv: 1 },
      { topic: "Trình bày thông tin ở dạng bảng", type: "mc", q: "Muốn làm cột “Họ và tên” của bảng rộng hơn, em đưa con trỏ chuột vào đường biên của cột cho đến khi con trỏ thành mũi tên hai chiều rồi:", o: ["Kéo thả chuột sang ngang", "Nhấn phím Enter", "Nháy đúp chuột vào giữa một ô", "Nhấn phím Delete"], x: "Khi con trỏ thành mũi tên hai chiều ở đường biên cột, kéo thả chuột để đổi độ rộng của cột; làm tương tự ở đường biên hàng để đổi độ cao của hàng.", lv: 1 },
      { topic: "Trình bày thông tin ở dạng bảng", type: "tf4", q: "Mỗi ý sau về bảng trong văn bản đúng hay sai?", o: ["Mỗi ô của bảng có thể chứa chữ hoặc số.", "Sau khi đã tạo bảng thì không thể thêm hàng mới.", "Có thể xóa một cột mà không xóa cả bảng.", "Bảng chỉ có trong phần mềm bảng tính, phần mềm soạn thảo văn bản không tạo được bảng."], a: [true, false, true, false], x: "a), c) Đúng: ô chứa được chữ, số (cả hình); có lệnh xóa riêng từng hàng, từng cột. b) Sai: có thể chèn thêm hàng, cột vào bảng đã tạo. d) Sai: phần mềm soạn thảo văn bản có công cụ tạo bảng.", lv: 2 },
      { topic: "Trình bày thông tin ở dạng bảng", type: "order", q: "Sắp xếp các việc cần làm để trình bày danh sách tổ ở dạng bảng theo đúng thứ tự.", o: ["Đặt con trỏ soạn thảo tại vị trí cần chèn bảng", "Mở lệnh tạo bảng và chọn số hàng, số cột", "Nhập nội dung vào từng ô", "Căn chỉnh, kẻ khung cho bảng đẹp và dễ đọc"], x: "Trước hết đặt con trỏ ở chỗ muốn có bảng, tạo bảng với số hàng, cột cần dùng, nhập nội dung vào các ô, cuối cùng định dạng bảng.", lv: 3 },
      { topic: "Trình bày thông tin ở dạng bảng", type: "num", q: "Lan lập thời khóa biểu buổi sáng gồm 5 ngày (thứ Hai đến thứ Sáu), mỗi ngày 5 tiết. Hàng đầu ghi tên các ngày, các hàng còn lại mỗi hàng một tiết. Bảng của Lan cần bao nhiêu hàng?", ans: 6, unit: "hàng", x: "5 tiết cần 5 hàng, thêm 1 hàng đầu ghi tên các ngày: 5 + 1 = 6 hàng.", lv: 3 },
      { topic: "Tìm kiếm và thay thế", type: "mc", q: "Trong phần mềm soạn thảo văn bản, lệnh Find và lệnh Replace nằm ở nhóm lệnh nào của thẻ Home?", o: ["Editing", "Font", "Paragraph", "Styles"], x: "Nhóm Editing ở cuối thẻ Home có lệnh Find (tìm kiếm) và Replace (thay thế).", lv: 1 },
      { topic: "Tìm kiếm và thay thế", type: "mc", q: "Minh gõ “hoc sinh” vào ô tìm kiếm thì máy báo không tìm thấy, dù văn bản có rất nhiều chữ “học sinh”. Vì sao?", o: ["Vì từ cần tìm phải gõ đúng như trong văn bản, kể cả dấu tiếng Việt", "Vì lệnh tìm kiếm chỉ tìm được số, không tìm được chữ", "Vì văn bản quá dài nên máy không tìm được", "Vì phải in văn bản ra giấy rồi mới tìm được"], x: "Máy chỉ tìm đúng chuỗi kí tự đã gõ. “hoc sinh” (không dấu) khác “học sinh” (có dấu), nên không tìm thấy. Cần gõ đúng từ cần tìm.", lv: 2 },
      { topic: "Tìm kiếm và thay thế", type: "order", q: "Sắp xếp các bước tìm từ “Internet” trong một văn bản dài theo đúng thứ tự.", o: ["Mở ngăn tìm kiếm ở bên trái văn bản", "Gõ “Internet” vào ô tìm kiếm", "Nhấn phím Enter để máy bắt đầu tìm", "Xem các chỗ có từ “Internet” được đánh dấu trong văn bản"], x: "Mở ngăn tìm kiếm, gõ từ cần tìm, nhấn Enter; mọi chỗ có từ đó được đánh dấu trong văn bản và hiện thành danh sách ở ngăn tìm kiếm để em nháy vào xem từng chỗ.", lv: 3 },
    ]
  },
  "tin6-gk2-de2": {
    note: "Sách Kết nối tri thức, nửa đầu học kì II: Bài 9 An toàn thông tin trên Internet; Bài 10 Sơ đồ tư duy; Bài 11 Định dạng văn bản; Bài 12 Trình bày thông tin ở dạng bảng; Bài 13 Thực hành: Tìm kiếm và thay thế. Có trường dạy Bài 9 ở học kì I, phụ huynh đối chiếu với đề cương của trường. Đề không có phần thực hành trên máy. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Có lời giải từng câu.",
    questions: [
      { topic: "An toàn thông tin trên Internet", type: "mc", q: "Để bảo vệ tài khoản của mình trên mạng, em nên:", o: ["Đặt mật khẩu khó đoán và không cho người khác biết", "Dùng tên của mình làm mật khẩu cho dễ nhớ", "Ghi mật khẩu lên trang bìa vở để khỏi quên", "Cho bạn thân mượn tài khoản để cùng dùng"], x: "Mật khẩu khó đoán và chỉ mình biết giúp người khác không vào được tài khoản. Mật khẩu là tên mình, ghi ở chỗ ai cũng thấy hay đưa cho người khác đều dễ bị lộ.", lv: 1 },
      { topic: "An toàn thông tin trên Internet", type: "mc", q: "Vì sao không nên đi gặp riêng một người mà em chỉ quen qua mạng?", o: ["Vì người đó có thể không giống như họ tự giới thiệu và có thể gây nguy hiểm cho em", "Vì gặp mặt sẽ làm tốn tiền đi lại", "Vì luật không cho phép học sinh ra khỏi nhà", "Vì người quen qua mạng không biết nói chuyện"], x: "Trên mạng, ai cũng có thể khai tên, tuổi, hình ảnh giả. Người lạ có thể lợi dụng, lừa gạt, làm hại em khi gặp riêng. Muốn gặp thì phải nói với bố mẹ và có người lớn đi cùng.", lv: 2 },
      { topic: "An toàn thông tin trên Internet", type: "mc", q: "Nam liên tục nhận được tin nhắn chế giễu, xúc phạm từ một nhóm bạn trên mạng. Nam nên làm gì?", o: ["Không đáp trả, lưu lại tin nhắn làm bằng chứng, chặn nhóm đó và báo bố mẹ, thầy cô", "Nhắn lại những lời nặng nề hơn để nhóm đó sợ", "Im lặng chịu đựng, không kể với ai", "Xóa tài khoản và không dùng mạng nữa"], x: "Đáp trả làm sự việc căng thẳng hơn; im lặng khiến việc đó kéo dài. Cách đúng là không trả lời, giữ bằng chứng, chặn người gửi và nói với người lớn để được giúp đỡ.", lv: 3 },
      { topic: "Sơ đồ tư duy", type: "mc", q: "Phần mềm chuyên dùng để tạo sơ đồ tư duy trên máy tính là:", o: ["MindMaple Lite", "Microsoft Word", "Paint", "Google Chrome"], x: "MindMaple Lite là phần mềm tạo sơ đồ tư duy: có sẵn chủ đề chính, thêm được chủ đề nhánh, chi tiết, hình ảnh, màu sắc. Word soạn văn bản, Paint vẽ hình, Chrome là trình duyệt web.", lv: 1 },
      { topic: "Sơ đồ tư duy", type: "mc", q: "Trong sơ đồ tư duy, hình ảnh và màu sắc được dùng để:", o: ["Làm sơ đồ sinh động, dễ nhìn, dễ nhớ hơn", "Thay cho chủ đề chính", "Che bớt các chi tiết không cần thiết", "Làm sơ đồ in được trên giấy"], x: "Não bộ ghi nhớ hình ảnh, màu sắc tốt, nên sơ đồ tư duy dùng chúng để các ý dễ nhìn, dễ nhớ; chủ đề chính và các chi tiết vẫn phải có.", lv: 1 },
      { topic: "Sơ đồ tư duy", type: "num", q: "Sơ đồ tư duy ở hình có bao nhiêu chủ đề nhánh?", svg: '<svg viewBox="0 0 320 200"><line x1="160" y1="100" x2="62" y2="40"/><line x1="160" y1="100" x2="258" y2="40"/><line x1="160" y1="100" x2="62" y2="160"/><line x1="160" y1="100" x2="258" y2="160"/><ellipse cx="160" cy="100" rx="46" ry="22" fill="sun-soft"/><text x="160" y="105" text-anchor="middle" font-size="15" fill="ink">Vườn rau</text><rect x="20" y="24" width="84" height="32" rx="6" fill="acc-soft"/><text x="62" y="45" text-anchor="middle" font-size="14" fill="ink">Loại rau</text><rect x="216" y="24" width="84" height="32" rx="6" fill="acc-soft"/><text x="258" y="45" text-anchor="middle" font-size="14" fill="ink">Dụng cụ</text><rect x="20" y="144" width="84" height="32" rx="6" fill="acc-soft"/><text x="62" y="165" text-anchor="middle" font-size="14" fill="ink">Chăm sóc</text><rect x="216" y="144" width="84" height="32" rx="6" fill="acc-soft"/><text x="258" y="165" text-anchor="middle" font-size="14" fill="ink">Thu hoạch</text><text x="62" y="76" text-anchor="middle" font-size="13" fill="muted">cải, rau muống</text><text x="258" y="76" text-anchor="middle" font-size="13" fill="muted">cuốc, bình tưới</text><text x="62" y="192" text-anchor="middle" font-size="13" fill="muted">tưới nước, nhổ cỏ</text><text x="258" y="192" text-anchor="middle" font-size="13" fill="muted">sáng thứ Bảy</text></svg>', ans: 4, unit: "chủ đề nhánh", x: "Chủ đề chính “Vườn rau” ở giữa; bốn ô nối với nó (Loại rau, Dụng cụ, Chăm sóc, Thu hoạch) là 4 chủ đề nhánh. Các chữ nhỏ bên dưới mỗi ô là chi tiết của nhánh.", lv: 2 },
      { topic: "Sơ đồ tư duy", type: "mc", q: "Lan vẽ sơ đồ tư duy tóm tắt bài học nhưng chép nguyên từng câu dài trong sách lên các nhánh. Nhận xét đúng là:", o: ["Nên thay bằng từ khóa ngắn gọn để sơ đồ dễ nhìn, dễ nhớ", "Làm vậy là tốt vì càng nhiều chữ càng đầy đủ", "Nên bỏ hết chữ, chỉ để hình ảnh", "Nên chép cả bài vào ô chủ đề chính"], x: "Ưu điểm của sơ đồ tư duy là ngắn gọn, trực quan. Nhánh ghi câu dài làm sơ đồ rối, khó nhớ; chỉ nên ghi từ khóa, ý chính. Bỏ hết chữ thì không hiểu được sơ đồ.", lv: 2 },
      { topic: "Sơ đồ tư duy", type: "mc", q: "Minh muốn tóm tắt chương “Nhà ở” gồm 3 bài để ôn thi. Cách làm hợp lí nhất là:", o: ["Vẽ sơ đồ tư duy với chủ đề chính là tên chương, mỗi bài là một chủ đề nhánh kèm các ý chính", "Chép lại toàn bộ 3 bài trong sách vào vở", "Chỉ ghi tên 3 bài, không ghi ý chính", "Vẽ 3 sơ đồ tư duy rời nhau, không có chủ đề chính"], x: "Sơ đồ tư duy một trang: tên chương ở giữa, mỗi bài một nhánh, dưới mỗi nhánh là các ý chính. Cách này ngắn gọn, nhìn thấy cả chương và mối liên hệ giữa các bài; chép hết sách thì dài, chỉ ghi tên bài thì thiếu ý.", lv: 3 },
      { topic: "Định dạng văn bản", type: "mc", q: "Để chọn cỡ chữ cho phần văn bản đang chọn, em dùng nhóm lệnh nào?", o: ["Font", "Paragraph", "Table", "Page Setup"], x: "Nhóm Font gồm các lệnh về chữ, trong đó có ô chọn cỡ chữ. Paragraph định dạng đoạn, Table làm việc với bảng, Page Setup đặt trang.", lv: 1 },
      { topic: "Định dạng văn bản", type: "match", q: "Nối mỗi nút lệnh với tác dụng của nó.", l: ["Nút B (Bold)", "Nút I (Italic)", "Nút U (Underline)"], r: ["In đậm", "In nghiêng", "Gạch chân", "Căn giữa"], x: "B là in đậm, I là in nghiêng, U là gạch chân. Căn giữa là lệnh định dạng đoạn, không phải nút nào trong ba nút trên.", lv: 1 },
      { topic: "Định dạng văn bản", type: "mc", q: "Định dạng trang văn bản gồm các việc:", o: ["Chọn hướng trang, đặt lề trang, chọn khổ giấy", "Chọn phông chữ, cỡ chữ, màu chữ cho cả trang", "Căn lề đoạn, đặt khoảng cách dòng trong trang", "Chèn bảng, chèn hình ảnh vào trang"], x: "Định dạng trang quyết định hình dáng chung của trang in: hướng trang (đứng, ngang), lề trang (trên, dưới, trái, phải) và khổ giấy. Phông chữ thuộc định dạng kí tự, căn lề đoạn thuộc định dạng đoạn.", lv: 1 },
      { topic: "Định dạng văn bản", type: "mc", q: "Phát biểu nào đúng về định dạng đoạn văn bản?", o: ["Chỉ cần đặt con trỏ soạn thảo trong đoạn, không cần chọn cả đoạn", "Phải xóa đoạn rồi gõ lại mới định dạng được", "Định dạng đoạn chỉ làm được trước khi gõ nội dung", "Mỗi đoạn chỉ định dạng được một lần"], x: "Định dạng đoạn áp dụng cho cả đoạn chứa con trỏ, nên chỉ cần đặt con trỏ vào đoạn (muốn định dạng nhiều đoạn thì chọn các đoạn đó). Có thể định dạng lại bao nhiêu lần cũng được.", lv: 2 },
      { topic: "Định dạng văn bản", type: "tf", q: "Thay đổi khoảng cách giữa các dòng trong một đoạn là định dạng kí tự.", a: false, x: "Sai. Khoảng cách dòng, căn lề, thụt đầu dòng là định dạng đoạn văn bản. Định dạng kí tự chỉ thay đổi phông, cỡ, kiểu, màu của chữ.", lv: 2 },
      { topic: "Định dạng văn bản", type: "mc", q: "Lề trang là:", o: ["Khoảng trống giữa mép giấy và phần văn bản", "Dòng đầu tiên của mỗi trang", "Số thứ tự của trang in ở dưới trang", "Đường kẻ bao quanh một đoạn văn bản"], x: "Lề trang là phần để trống ở bốn phía của trang (trên, dưới, trái, phải), văn bản nằm bên trong lề. Lề giúp trang không bị chữ sát mép và có chỗ đóng tập.", lv: 2 },
      { topic: "Định dạng văn bản", type: "mc", q: "Bảng điểm của lớp có 10 cột, in trên trang đứng thì bị thiếu mấy cột cuối. Cách khắc phục hợp lí nhất là:", o: ["Đổi hướng trang sang trang ngang", "Xóa bớt các cột cuối cho vừa trang", "In mỗi cột ra một tờ rồi dán lại", "Tăng cỡ chữ cho dễ nhìn"], x: "Trang ngang rộng hơn trang đứng nên chứa được nhiều cột hơn. Xóa cột thì mất dữ liệu, tăng cỡ chữ càng tràn, in từng cột rất bất tiện.", lv: 3 },
      { topic: "Định dạng văn bản", type: "tf4", q: "Hà soạn một thông báo để dán ở bảng tin của lớp. Mỗi cách làm sau có hợp lí không?", o: ["Chọn cỡ chữ 8 để thông báo gọn trong nửa trang.", "Dùng màu chữ đỏ chói cho mọi dòng.", "Căn lề và chọn khoảng cách dòng vừa phải để dễ đọc.", "Đọc lại, sửa lỗi chính tả trước khi in."], a: [false, false, true, true], x: "a) Không: cỡ chữ 8 quá nhỏ, dán ở bảng tin không ai đọc được. b) Không: cả trang đỏ chói gây mỏi mắt; màu nổi chỉ nên dùng ở vài chỗ cần nhấn. c), d) Hợp lí: trình bày thoáng, dễ đọc và không có lỗi chính tả.", lv: 3 },
      { topic: "Trình bày thông tin ở dạng bảng", type: "mc", q: "Lệnh Merge Cells trong bảng dùng để:", o: ["Gộp nhiều ô đã chọn thành một ô", "Tách một ô thành nhiều ô", "Xóa cả bảng", "Đổi màu chữ trong ô"], x: "Merge Cells gộp các ô được chọn (cùng hàng hoặc cùng cột) thành một ô, thường dùng để ghi tiêu đề chung. Tách ô là Split Cells.", lv: 1 },
      { topic: "Trình bày thông tin ở dạng bảng", type: "mc", q: "Nội dung nào dưới đây phù hợp nhất để trình bày ở dạng bảng?", o: ["Lịch trực nhật của các tổ trong tuần", "Một bài văn tả cảnh", "Một lá thư gửi bạn", "Một bài thơ bốn chữ"], x: "Lịch trực nhật có nhiều tổ, nhiều ngày cần tra cứu nhanh nên trình bày dạng bảng là rõ nhất: mỗi hàng một tổ, mỗi cột một ngày. Bài văn, lá thư, bài thơ là văn bản viết liền mạch, không cần bảng.", lv: 1 },
      { topic: "Trình bày thông tin ở dạng bảng", type: "fill", q: "Để tạo bảng trong văn bản, em chọn thẻ ___ rồi nháy nút Table.", ans: ["Insert", "insert", "INSERT"], x: "Nút Table nằm ở thẻ Insert (chèn). Nháy nút Table rồi kéo chọn số hàng, số cột hoặc dùng lệnh Insert Table để nhập số hàng, số cột.", lv: 1 },
      { topic: "Trình bày thông tin ở dạng bảng", type: "mc", q: "Bảng ở hình có bao nhiêu hàng và bao nhiêu cột?", svg: '<svg viewBox="0 0 320 170"><line x1="25" y1="25" x2="295" y2="25"/><line x1="25" y1="55" x2="295" y2="55"/><line x1="25" y1="85" x2="295" y2="85"/><line x1="25" y1="115" x2="295" y2="115"/><line x1="25" y1="145" x2="295" y2="145"/><line x1="25" y1="25" x2="25" y2="145"/><line x1="115" y1="25" x2="115" y2="145"/><line x1="205" y1="25" x2="205" y2="145"/><line x1="295" y1="25" x2="295" y2="145"/><text x="70" y="45" text-anchor="middle" font-size="14" fill="ink">Họ tên</text><text x="160" y="45" text-anchor="middle" font-size="14" fill="ink">Tổ</text><text x="250" y="45" text-anchor="middle" font-size="14" fill="ink">Điểm</text><text x="70" y="75" text-anchor="middle" font-size="14" fill="ink">An</text><text x="160" y="75" text-anchor="middle" font-size="14" fill="ink">1</text><text x="250" y="75" text-anchor="middle" font-size="14" fill="ink">9</text><text x="70" y="105" text-anchor="middle" font-size="14" fill="ink">Bình</text><text x="160" y="105" text-anchor="middle" font-size="14" fill="ink">2</text><text x="250" y="105" text-anchor="middle" font-size="14" fill="ink">8</text><text x="70" y="135" text-anchor="middle" font-size="14" fill="ink">Chi</text><text x="160" y="135" text-anchor="middle" font-size="14" fill="ink">1</text><text x="250" y="135" text-anchor="middle" font-size="14" fill="ink">10</text></svg>', o: ["4 hàng, 3 cột", "3 hàng, 4 cột", "4 hàng, 4 cột", "3 hàng, 3 cột"], x: "Đếm theo chiều ngang có 4 hàng (hàng tiêu đề và 3 hàng tên bạn: An, Bình, Chi); theo chiều dọc có 3 cột (Họ tên, Tổ, Điểm). Hàng tiêu đề cũng là một hàng của bảng.", lv: 2 },
      { topic: "Trình bày thông tin ở dạng bảng", type: "mc", q: "Danh sách lớp trong bảng xếp theo thứ tự tên: An, Cường, Dũng… Có bạn mới tên Bình cần thêm vào giữa An và Cường. Cách làm đúng là:", o: ["Nháy vào ô ở hàng của An rồi chèn một hàng mới phía dưới, nhập tên Bình", "Gõ tên Bình nối vào ô của An", "Xóa cả bảng rồi tạo lại từ đầu", "Gõ tên Bình ở hàng cuối bảng rồi để nguyên"], x: "Chèn một hàng mới ngay dưới hàng của An rồi nhập tên Bình thì danh sách vẫn đúng thứ tự. Gõ chung ô của An hay để ở cuối bảng đều sai thứ tự; tạo lại bảng mất công.", lv: 3 },
      { topic: "Trình bày thông tin ở dạng bảng", type: "tf4", q: "Minh làm bảng “Danh sách tổ 1” nhưng thừa 2 hàng trống ở cuối và thiếu cột “Ghi chú”. Mỗi cách làm sau đúng hay sai?", o: ["Chọn 2 hàng trống rồi dùng lệnh xóa hàng.", "Xóa cả bảng rồi tạo lại từ đầu là cách duy nhất.", "Dùng lệnh chèn cột để thêm cột “Ghi chú” vào bảng.", "Gõ các ghi chú ra ngoài bảng, cạnh lề phải."], a: [true, false, true, false], x: "a), c) Đúng: bảng có lệnh xóa hàng, chèn cột, sửa được ngay trên bảng đang có. b) Sai: không cần tạo lại. d) Sai: ghi chú để ngoài bảng thì không thẳng hàng với tên bạn, khó đọc.", lv: 3 },
      { topic: "Tìm kiếm và thay thế", type: "mc", q: "Trong hộp thoại Find and Replace, nút nào đưa tới chỗ tiếp theo có từ đã gõ ở ô Find what?", o: ["Find Next", "Cancel", "More >>", "Go To"], x: "Find Next tìm đến chỗ tiếp theo có từ ở ô Find what. Cancel đóng hộp thoại, More >> mở thêm các tùy chọn, Go To là thẻ dùng để đi tới một trang.", lv: 1 },
      { topic: "Tìm kiếm và thay thế", type: "tf4", q: "Mỗi ý sau về tìm kiếm và thay thế trong văn bản đúng hay sai?", o: ["Lệnh tìm kiếm giúp tìm nhanh một từ trong văn bản dài.", "Lệnh thay thế chỉ dùng được khi văn bản có đúng một chỗ cần thay.", "Khi thay thế, có thể xem từng chỗ tìm thấy rồi quyết định thay hay bỏ qua.", "Chỉ tìm được từ trong văn bản dài dưới một trang."], a: [true, false, true, false], x: "a), c) Đúng: máy tìm trong cả văn bản, dừng ở từng chỗ để em quyết định. b) Sai: thay thế dùng được cho nhiều chỗ, thậm chí thay tất cả một lần. d) Sai: tìm được trong văn bản dài bao nhiêu cũng được.", lv: 2 },
      { topic: "Tìm kiếm và thay thế", type: "mc", q: "Bài văn dài 20 trang viết sai “Hà nội” ở rất nhiều chỗ, cần sửa thành “Hà Nội”. Cách làm nhanh và đúng nhất là:", o: ["Dùng lệnh thay thế: tìm “Hà nội”, thay bằng “Hà Nội”, chọn thay tất cả", "Đọc lại từng trang và sửa tay từng chỗ", "Xóa cả bài rồi gõ lại", "Chỉ sửa chỗ đầu tiên, các chỗ sau để nguyên"], x: "Lệnh thay thế đổi mọi chỗ “Hà nội” thành “Hà Nội” trong một lần, không sót. Sửa tay 20 trang lâu và dễ sót; gõ lại càng mất công.", lv: 3 }
    ]
  },
  /* ---------- Tin học 6 · Kiểm tra cuối năm học (Kết nối tri thức) ----------
     Phạm vi học kì II ghi ở note: Chủ đề 6 (Bài 15–17) và ôn Bài 9–13 (chữ chủ đề như kho giữa kì II, mỗi đề 1 câu một bài); Bài 14
     (thực hành tổng hợp) không ra câu. Câu tự soạn, mức độ lv ở từng câu (Phiên N22b). Hai đề là kho của đề ngẫu nhiên
     "tin6-ck2-ngau-nhien" (không có câu riêng nên không ghi vào file này; ma trận ở data/banks/index.js); hai đề cùng phân bố chủ đề
     và mức như ma trận, nên ô nào cũng có gấp đôi số câu ô đó rút. Cách xếp mức: nhận ra thuật toán, đầu vào, đầu ra, cách mô tả, đọc
     bước tiếp theo trong sơ đồ khối, tên cấu trúc, ngôn ngữ lập trình, khối lệnh nhận dữ liệu là Biết; cho biết sơ đồ mô tả gì, cấu
     trúc nào, điều kiện ghi ở hình thoi, đánh giá một bước, các ý về một sơ đồ khối hay một chương trình là Hiểu; sắp xếp các khối,
     tính kết quả của sơ đồ khối hay chương trình Scratch, chọn điều kiện, sửa chương trình, xử lí tình huống là Vận dụng. Sơ đồ khối
     vẽ theo quy ước của sách: Bắt đầu, Kết thúc là hình bầu dục tô moc-soft; nhập, thông báo là hình bình hành tô ioe-soft; bước xử
     lí là hình chữ nhật tô sun-soft; điều kiện là hình thoi tô ok-soft, hai đường ra ghi “Đúng”, “Sai” (chữ muted); mũi tên là
     polyline đi từ giữa một cạnh (đỉnh hình thoi) tới giữa một cạnh khác, đầu mũi tên là tam giác tô ink; phép gán viết “x ← …” như
     sách. Chương trình Scratch vẽ mỗi khối một hình chữ nhật bo góc tô theo nhóm lệnh; khối bên trong khối lặp, khối nếu thì lùi vào
     18, cuối khối đó có thanh đóng không có chữ, bên trái có thân chữ C như hình của sách; tên khối theo sách Tin học 6 (“đặt … là
     …”, “còn không thì”), chữ trong ngoặc kép là chữ nhân vật nói, chữ không có ngoặc là tên biến. tests/tin-congnghe6-ck2.js đọc lại
     các hình, chạy thử thuật toán và chương trình. Mọi hình sơ đồ khối đều cho thấy quy ước vẽ, nên kho không có câu hỏi hình nào
     dùng cho bước nào. Câu ở hai ô khác nhau, cả hai câu của một ô, có thể cùng được rút vào một đề, nên đề bài, các lựa chọn, lời
     giải không ghi sẵn đáp án của câu khác; mỗi khối lệnh, nhóm lệnh, nút lệnh chỉ được hỏi ở một câu trong cả kho. */
  "tin6-ck2-de1": {
    note: "Sách Kết nối tri thức, học kì II: Chủ đề 6 Giải quyết vấn đề với sự trợ giúp của máy tính (Bài 15 Thuật toán, Bài 16 Các cấu trúc điều khiển, Bài 17 Chương trình máy tính); ôn Bài 9–13 (an toàn thông tin trên Internet, sơ đồ tư duy, định dạng văn bản, trình bày thông tin ở dạng bảng, tìm kiếm và thay thế). Đề không có phần thực hành trên máy. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Có lời giải từng câu.",
    questions: [
      { topic: "Thuật toán", type: "mc", q: "Trường hợp nào dưới đây là một thuật toán?", o: ["Các bước đánh số để đặt giờ báo thức trên điện thoại", "Danh sách đồ dùng cần mang theo khi đi học mỗi ngày", "Bảng ghi giờ thức dậy của từng người trong nhà", "Lời mẹ dặn: “Con nhớ ngủ sớm nhé!”"], x: "Thuật toán gồm các bước làm được nêu rõ, xếp theo đúng thứ tự để làm xong một việc. Các bước đánh số để đặt giờ báo thức là một thuật toán; danh sách đồ dùng, bảng ghi giờ, lời dặn không nêu các bước làm.", lv: 1 },
      { topic: "Thuật toán", type: "mc", q: "Thuật toán tính tuổi của Lan vào năm 2030. Dữ liệu nào là đầu vào của thuật toán?", o: ["Năm sinh của Lan", "Tuổi của Lan vào năm 2030", "Tên trường Lan đang học", "Số bạn trong lớp của Lan"], x: "Muốn biết Lan bao nhiêu tuổi vào năm 2030 thì cần biết năm sinh của Lan: đó là dữ liệu đưa vào thuật toán (đầu vào).", lv: 1 },
      { topic: "Thuật toán", type: "mc", q: "Lan và Hà cùng thực hiện đúng các bước của một thuật toán, với cùng một đầu vào. Kết quả hai bạn nhận được sẽ:", o: ["Giống nhau", "Khác nhau, vì hai bạn khác nhau", "Chỉ giống nhau khi hai bạn làm cùng lúc", "Không thể biết trước được"], x: "Làm đủ và đúng thứ tự các bước của cùng một thuật toán, với đầu vào như nhau, thì người nào làm kết quả cũng như nhau.", lv: 1 },
      { topic: "Thuật toán", type: "mc", q: "Sơ đồ khối ở hình mô tả thuật toán gì?", svg: '<svg viewBox="0 0 320 256"><polyline points="160,36 160,56" fill="none"/><polygon points="160,56 155,47 165,47" fill="ink"/><polyline points="160,100 160,120" fill="none"/><polygon points="160,120 155,111 165,111" fill="ink"/><polyline points="160,150 160,170" fill="none"/><polygon points="160,170 155,161 165,161" fill="ink"/><polyline points="160,200 160,220" fill="none"/><polygon points="160,220 155,211 165,211" fill="ink"/><ellipse cx="160" cy="21" rx="50" ry="15" fill="moc-soft"/><text x="160" y="26" text-anchor="middle" font-size="14" fill="ink">Bắt đầu</text><polygon points="70,56 260,56 250,100 60,100" fill="ioe-soft"/><text x="160" y="74.5" text-anchor="middle" font-size="14" fill="ink">Nhập số quyển vở n,</text><text x="160" y="91.5" text-anchor="middle" font-size="14" fill="ink">giá một quyển g</text><rect x="95" y="120" width="130" height="30" fill="sun-soft"/><text x="160" y="140" text-anchor="middle" font-size="14" fill="ink">T ← n × g</text><polygon points="95,170 235,170 225,200 85,200" fill="ioe-soft"/><text x="160" y="190" text-anchor="middle" font-size="14" fill="ink">Thông báo T</text><ellipse cx="160" cy="235" rx="50" ry="15" fill="moc-soft"/><text x="160" y="240" text-anchor="middle" font-size="14" fill="ink">Kết thúc</text></svg>', o: ["Tính số tiền mua n quyển vở", "Tính số quyển vở mua được", "Tính giá tiền của một quyển vở", "Tìm quyển vở có giá rẻ nhất"], x: "Đầu vào là số quyển vở n và giá một quyển g. Bước xử lí T ← n × g tính số tiền mua n quyển, rồi thông báo T.", lv: 2 },
      { topic: "Thuật toán", type: "mc", q: "Hà gửi ảnh cho bạn qua ứng dụng nhắn tin theo các bước: 1) Mở ứng dụng; 2) Chọn tên bạn nhận; 3) Chọn bức ảnh; 4) Nháy nút Gửi. Hôm nay Hà làm bước 4 ngay sau bước 2, rồi mới làm bước 3. Kết quả là:", o: ["Bạn nhận không nhận được bức ảnh", "Bạn nhận vẫn nhận được bức ảnh", "Bức ảnh được gửi cho mọi người", "Ứng dụng tự đổi lại thứ tự các bước"], x: "Phải chọn ảnh trước rồi mới nháy Gửi. Nháy Gửi khi chưa chọn ảnh thì không có ảnh nào được gửi đi, nên bạn không nhận được ảnh: thứ tự các bước rất quan trọng.", lv: 2 },
      { topic: "Thuật toán", type: "order", q: "Sắp xếp các khối dưới đây theo đúng thứ tự để được sơ đồ khối của thuật toán đổi số đo thời gian h giờ m phút ra phút.", o: ["Bắt đầu", "Nhập số giờ h, số phút m", "p ← h × 60", "p ← p + m", "Thông báo p", "Kết thúc"], x: "Bắt đầu, nhập h, m, đổi số giờ ra phút p ← h × 60 (1 giờ = 60 phút), cộng thêm số phút p ← p + m, thông báo p rồi kết thúc. Bước p ← p + m dùng giá trị p vừa tính nên phải đứng sau bước p ← h × 60.", lv: 3 },
      { topic: "Thuật toán", type: "num", q: "Thực hiện thuật toán ở hình với đầu vào a = 9. Số được thông báo là bao nhiêu?", svg: '<svg viewBox="0 0 320 292"><polyline points="160,36 160,56" fill="none"/><polygon points="160,56 155,47 165,47" fill="ink"/><polyline points="160,86 160,106" fill="none"/><polygon points="160,106 155,97 165,97" fill="ink"/><polyline points="160,136 160,156" fill="none"/><polygon points="160,156 155,147 165,147" fill="ink"/><polyline points="160,186 160,206" fill="none"/><polygon points="160,206 155,197 165,197" fill="ink"/><polyline points="160,236 160,256" fill="none"/><polygon points="160,256 155,247 165,247" fill="ink"/><ellipse cx="160" cy="21" rx="50" ry="15" fill="moc-soft"/><text x="160" y="26" text-anchor="middle" font-size="14" fill="ink">Bắt đầu</text><polygon points="110,56 220,56 210,86 100,86" fill="ioe-soft"/><text x="160" y="76" text-anchor="middle" font-size="14" fill="ink">Nhập a</text><rect x="95" y="106" width="130" height="30" fill="sun-soft"/><text x="160" y="126" text-anchor="middle" font-size="14" fill="ink">b ← a × 3</text><rect x="95" y="156" width="130" height="30" fill="sun-soft"/><text x="160" y="176" text-anchor="middle" font-size="14" fill="ink">c ← b − 4</text><polygon points="95,206 235,206 225,236 85,236" fill="ioe-soft"/><text x="160" y="226" text-anchor="middle" font-size="14" fill="ink">Thông báo c</text><ellipse cx="160" cy="271" rx="50" ry="15" fill="moc-soft"/><text x="160" y="276" text-anchor="middle" font-size="14" fill="ink">Kết thúc</text></svg>', ans: 23, x: "a = 9 nên b ← 9 × 3 = 27, rồi c ← 27 − 4 = 23. Thuật toán thông báo c, tức là 23.", lv: 3 },
      { topic: "Các cấu trúc điều khiển", type: "mc", q: "Câu “Nếu gõ đúng mật khẩu thì mở được tài khoản, còn không thì máy báo lỗi” mô tả cấu trúc nào?", o: ["Rẽ nhánh dạng đủ", "Rẽ nhánh dạng thiếu", "Lặp với số lần biết trước", "Tuần tự, không có điều kiện"], x: "Câu có hai việc: một việc khi điều kiện đúng (mở được tài khoản), một việc khi điều kiện sai (máy báo lỗi). Đó là cấu trúc rẽ nhánh dạng đủ.", lv: 1 },
      { topic: "Các cấu trúc điều khiển", type: "mc", q: "Một thuật toán chỉ có cấu trúc tuần tự. Các bước của nó được làm theo cách nào?", o: ["Lần lượt từng bước, từ bước đầu đến bước cuối", "Chỉ thực hiện những bước được đánh dấu", "Lặp lại một số bước cho đến khi dừng", "Chọn một trong hai bước tuỳ điều kiện"], x: "Ở cấu trúc tuần tự, các bước lần lượt được làm theo đúng thứ tự từ đầu đến cuối, bước nào cũng làm một lần.", lv: 1 },
      { topic: "Các cấu trúc điều khiển", type: "mc", q: "Quân định vẽ sơ đồ khối cho một trò chơi có rất nhiều bước và hỏi: “Chắc phải dùng thêm loại cấu trúc khác ngoài tuần tự, rẽ nhánh, lặp?” Câu trả lời đúng là:", o: ["Không cần, chỉ ba cấu trúc đó là vẽ được", "Cần thêm ít nhất hai cấu trúc khác nữa", "Trò chơi nhiều bước thì không vẽ được sơ đồ khối", "Chỉ cần dùng cấu trúc tuần tự là đủ"], x: "Mọi thuật toán, dù có rất nhiều bước, đều mô tả được chỉ với tuần tự, rẽ nhánh và lặp; không cần thêm loại cấu trúc nào khác.", lv: 1 },
      { topic: "Các cấu trúc điều khiển", type: "tf4", q: "Sơ đồ khối ở hình mô tả thuật toán xét kết quả một bài kiểm tra. Mỗi ý sau đúng hay sai?", svg: '<svg viewBox="0 0 320 296"><polyline points="160,36 160,57" fill="none"/><polygon points="160,57 155,48 165,48" fill="ink"/><polyline points="160,87 160,108" fill="none"/><polygon points="160,108 155,99 165,99" fill="ink"/><polyline points="100,133 80,133 80,183" fill="none"/><polygon points="80,183 75,174 85,174" fill="ink"/><text x="80" y="125" text-anchor="middle" font-size="13" fill="muted">Đúng</text><polyline points="220,133 240,133 240,183" fill="none"/><polygon points="240,183 235,174 245,174" fill="ink"/><text x="240" y="125" text-anchor="middle" font-size="13" fill="muted">Sai</text><polyline points="80,227 80,242 160,242 160,259" fill="none"/><polygon points="160,259 155,250 165,250" fill="ink"/><polyline points="240,227 240,242 160,242 160,259" fill="none"/><polygon points="160,259 155,250 165,250" fill="ink"/><ellipse cx="160" cy="21" rx="50" ry="15" fill="moc-soft"/><text x="160" y="26" text-anchor="middle" font-size="14" fill="ink">Bắt đầu</text><polygon points="95,57 235,57 225,87 85,87" fill="ioe-soft"/><text x="160" y="77" text-anchor="middle" font-size="14" fill="ink">Nhập điểm d</text><polygon points="160,108 220,133 160,158 100,133" fill="ok-soft"/><text x="160" y="138" text-anchor="middle" font-size="14" fill="ink">d ≥ 5?</text><polygon points="25,183 145,183 135,227 15,227" fill="ioe-soft"/><text x="80" y="201.5" text-anchor="middle" font-size="14" fill="ink">Thông báo</text><text x="80" y="218.5" text-anchor="middle" font-size="14" fill="ink">“Đạt”</text><polygon points="185,183 305,183 295,227 175,227" fill="ioe-soft"/><text x="240" y="201.5" text-anchor="middle" font-size="14" fill="ink">Thông báo</text><text x="240" y="218.5" text-anchor="middle" font-size="14" fill="ink">“Chưa đạt”</text><ellipse cx="160" cy="274" rx="50" ry="15" fill="moc-soft"/><text x="160" y="279" text-anchor="middle" font-size="14" fill="ink">Kết thúc</text></svg>', o: ["Nhập d = 8 thì thuật toán thông báo “Đạt”.", "Nhập d = 5 thì thuật toán thông báo “Chưa đạt”.", "Với mỗi lần nhập, thuật toán thông báo cả “Đạt” và “Chưa đạt”.", "Bước kiểm tra d ≥ 5 được thực hiện sau bước nhập điểm."], a: [true, false, false, true], x: "a) Đúng: 8 ≥ 5 nên đi theo nhánh Đúng. b) Sai: 5 ≥ 5 là đúng nên thông báo “Đạt”. c) Sai: mỗi lần chỉ đi theo một nhánh nên chỉ có một thông báo. d) Đúng: mũi tên đi từ bước nhập điểm xuống hình thoi.", lv: 2 },
      { topic: "Các cấu trúc điều khiển", type: "mc", q: "Trong sơ đồ khối ở hình, hình thoi “Bóng chưa đủ căng?” cùng bước “Bơm thêm một lần” tạo thành cấu trúc nào?", svg: '<svg viewBox="0 0 320 330"><polyline points="160,36 160,68" fill="none"/><polygon points="160,68 155,59 165,59" fill="ink"/><polyline points="160,124 160,161" fill="none"/><polygon points="160,161 155,152 165,152" fill="ink"/><text x="186" y="145" text-anchor="middle" font-size="13" fill="muted">Đúng</text><polyline points="75,176 30,176 30,54 160,54 160,68" fill="none"/><polygon points="160,68 155,59 165,59" fill="ink"/><polyline points="270,96 296,96 296,222 160,222 160,245" fill="none"/><polygon points="160,245 155,236 165,236" fill="ink"/><text x="284" y="88" text-anchor="middle" font-size="13" fill="muted">Sai</text><polyline points="160,275 160,293" fill="none"/><polygon points="160,293 155,284 165,284" fill="ink"/><ellipse cx="160" cy="21" rx="50" ry="15" fill="moc-soft"/><text x="160" y="26" text-anchor="middle" font-size="14" fill="ink">Bắt đầu</text><polygon points="160,68 270,96 160,124 50,96" fill="ok-soft"/><text x="160" y="101" text-anchor="middle" font-size="14" fill="ink">Bóng chưa đủ căng?</text><rect x="75" y="161" width="170" height="30" fill="sun-soft"/><text x="160" y="181" text-anchor="middle" font-size="14" fill="ink">Bơm thêm một lần</text><rect x="95" y="245" width="130" height="30" fill="sun-soft"/><text x="160" y="265" text-anchor="middle" font-size="14" fill="ink">Cất bơm</text><ellipse cx="160" cy="308" rx="50" ry="15" fill="moc-soft"/><text x="160" y="313" text-anchor="middle" font-size="14" fill="ink">Kết thúc</text></svg>', o: ["Cấu trúc lặp", "Cấu trúc tuần tự", "Cấu trúc rẽ nhánh", "Không có cấu trúc nào"], x: "Mũi tên từ bước “Bơm thêm một lần” quay về hình thoi, nên bước này được làm lại nhiều lần cho đến khi điều kiện sai (bóng đã đủ căng): đó là cấu trúc lặp.", lv: 2 },
      { topic: "Các cấu trúc điều khiển", type: "mc", q: "Khi vẽ sơ đồ khối cho câu “Nếu đến lớp muộn thì xin phép thầy cô trước khi vào lớp”, em ghi gì vào hình thoi?", o: ["Đến lớp muộn?", "Xin phép thầy cô", "Vào lớp", "Bắt đầu"], x: "Hình thoi ghi điều kiện cần kiểm tra: có đến lớp muộn hay không. “Xin phép thầy cô” là việc làm khi điều kiện đúng, ghi trong hình chữ nhật.", lv: 2 },
      { topic: "Các cấu trúc điều khiển", type: "num", q: "Sơ đồ khối ở hình tính tiền vé tham quan T (đồng) cho một nhóm n người. Nếu nhập n = 12 thì T được thông báo là bao nhiêu đồng?", svg: '<svg viewBox="0 0 320 398"><polyline points="160,36 160,57" fill="none"/><polygon points="160,57 155,48 165,48" fill="ink"/><polyline points="160,87 160,108" fill="none"/><polygon points="160,108 155,99 165,99" fill="ink"/><polyline points="100,133 80,133 80,185" fill="none"/><polygon points="80,185 75,176 85,176" fill="ink"/><text x="80" y="125" text-anchor="middle" font-size="13" fill="muted">Đúng</text><polyline points="220,133 240,133 240,185" fill="none"/><polygon points="240,185 235,176 245,176" fill="ink"/><text x="240" y="125" text-anchor="middle" font-size="13" fill="muted">Sai</text><polyline points="80,215 80,233 160,233 160,251" fill="none"/><polygon points="160,251 155,242 165,242" fill="ink"/><polyline points="240,215 240,233 160,233 160,251" fill="none"/><polygon points="160,251 155,242 165,242" fill="ink"/><polyline points="160,281 160,305" fill="none"/><polygon points="160,305 155,296 165,296" fill="ink"/><polyline points="160,335 160,359" fill="none"/><polygon points="160,359 155,350 165,350" fill="ink"/><ellipse cx="160" cy="21" rx="50" ry="15" fill="moc-soft"/><text x="160" y="26" text-anchor="middle" font-size="14" fill="ink">Bắt đầu</text><polygon points="85,57 245,57 235,87 75,87" fill="ioe-soft"/><text x="160" y="77" text-anchor="middle" font-size="14" fill="ink">Nhập số người n</text><polygon points="160,108 220,133 160,158 100,133" fill="ok-soft"/><text x="160" y="138" text-anchor="middle" font-size="14" fill="ink">n ≥ 10?</text><rect x="15" y="185" width="130" height="30" fill="sun-soft"/><text x="80" y="205" text-anchor="middle" font-size="14" fill="ink">g ← 40 000</text><rect x="175" y="185" width="130" height="30" fill="sun-soft"/><text x="240" y="205" text-anchor="middle" font-size="14" fill="ink">g ← 50 000</text><rect x="95" y="251" width="130" height="30" fill="sun-soft"/><text x="160" y="271" text-anchor="middle" font-size="14" fill="ink">T ← n × g</text><polygon points="95,305 235,305 225,335 85,335" fill="ioe-soft"/><text x="160" y="325" text-anchor="middle" font-size="14" fill="ink">Thông báo T</text><ellipse cx="160" cy="374" rx="50" ry="15" fill="moc-soft"/><text x="160" y="379" text-anchor="middle" font-size="14" fill="ink">Kết thúc</text></svg>', ans: 480000, unit: "đồng", x: "n = 12 thì điều kiện n ≥ 10 đúng, nên g ← 40 000. Sau đó T ← 12 × 40 000 = 480 000 (đồng).", lv: 3 },
      { topic: "Các cấu trúc điều khiển", type: "mc", q: "Sơ đồ khối ở hình dùng biến đếm d để viết chữ “A” đúng 10 lần. Hình thoi “?” cần ghi điều kiện nào?", svg: '<svg viewBox="0 0 320 330"><polyline points="160,36 160,55" fill="none"/><polygon points="160,55 155,46 165,46" fill="ink"/><polyline points="160,85 160,113" fill="none"/><polygon points="160,113 155,104 165,104" fill="ink"/><polyline points="160,163 160,189" fill="none"/><polygon points="160,189 155,180 165,180" fill="ink"/><text x="186" y="180" text-anchor="middle" font-size="13" fill="muted">Đúng</text><polyline points="160,219 160,239" fill="none"/><polygon points="160,239 155,230 165,230" fill="ink"/><polyline points="90,254 30,254 30,102 160,102 160,113" fill="none"/><polygon points="160,113 155,104 165,104" fill="ink"/><polyline points="215,138 296,138 296,276 160,276 160,293" fill="none"/><polygon points="160,293 155,284 165,284" fill="ink"/><text x="284" y="130" text-anchor="middle" font-size="13" fill="muted">Sai</text><ellipse cx="160" cy="21" rx="50" ry="15" fill="moc-soft"/><text x="160" y="26" text-anchor="middle" font-size="14" fill="ink">Bắt đầu</text><rect x="105" y="55" width="110" height="30" fill="sun-soft"/><text x="160" y="75" text-anchor="middle" font-size="14" fill="ink">d ← 0</text><polygon points="160,113 215,138 160,163 105,138" fill="ok-soft"/><text x="160" y="143" text-anchor="middle" font-size="14" fill="ink">?</text><rect x="90" y="189" width="140" height="30" fill="sun-soft"/><text x="160" y="209" text-anchor="middle" font-size="14" fill="ink">Viết chữ “A”</text><rect x="90" y="239" width="140" height="30" fill="sun-soft"/><text x="160" y="259" text-anchor="middle" font-size="14" fill="ink">d ← d + 1</text><ellipse cx="160" cy="308" rx="50" ry="15" fill="moc-soft"/><text x="160" y="313" text-anchor="middle" font-size="14" fill="ink">Kết thúc</text></svg>', o: ["d < 10?", "d = 10?", "d > 10?", "d ≤ 10?"], x: "d lần lượt bằng 0, 1, …, 9 thì còn viết, đủ 10 lần; khi d = 10 thì dừng. Điều kiện cần ghi là d < 10. Ghi d ≤ 10 thì viết 11 lần; ghi d = 10 hay d > 10 thì ngay từ đầu điều kiện đã sai, không viết lần nào.", lv: 3 },
      { topic: "Chương trình máy tính", type: "mc", q: "Tên nào dưới đây là tên một ngôn ngữ lập trình?", o: ["Python", "Tiếng Anh", "Microsoft Word", "Google Chrome"], x: "Python là một ngôn ngữ lập trình, như Scratch. Tiếng Anh là ngôn ngữ con người dùng hằng ngày; Microsoft Word, Google Chrome là phần mềm.", lv: 1 },
      { topic: "Chương trình máy tính", type: "mc", q: "Trong chương trình Scratch ở hình, khối lệnh nào nhận dữ liệu đầu vào do người dùng gõ từ bàn phím?", svg: '<svg viewBox="0 0 320 164"><rect x="10" y="6" width="199" height="28" rx="6" fill="sun-soft"/><text x="20" y="25" font-size="14" fill="ink">khi nhấn vào lá cờ xanh</text><rect x="10" y="37" width="222" height="28" rx="6" fill="ioe-soft"/><text x="20" y="56" font-size="14" fill="ink">hỏi “Mấy hộp bánh?” và đợi</text><rect x="10" y="68" width="145" height="28" rx="6" fill="ok-soft"/><text x="20" y="87" font-size="14" fill="ink">đặt h là trả lời</text><rect x="10" y="99" width="130" height="28" rx="6" fill="ok-soft"/><text x="20" y="118" font-size="14" fill="ink">đặt b là h + h</text><rect x="10" y="130" width="161" height="28" rx="6" fill="moc-soft"/><text x="20" y="149" font-size="14" fill="ink">nói b trong 2 giây</text></svg>', o: ["hỏi “Mấy hộp bánh?” và đợi", "khi nhấn vào lá cờ xanh", "đặt b là h + h", "nói b trong 2 giây"], x: "Khối «hỏi … và đợi» hiện câu hỏi rồi chờ người dùng gõ câu trả lời từ bàn phím: đó là bước nhận dữ liệu đầu vào.", lv: 1 },
      { topic: "Chương trình máy tính", type: "tf4", q: "Chạy chương trình Scratch ở hình. Mỗi ý sau đúng hay sai?", svg: '<svg viewBox="0 0 320 208"><rect x="10" y="6" width="199" height="28" rx="6" fill="sun-soft"/><text x="20" y="25" font-size="14" fill="ink">khi nhấn vào lá cờ xanh</text><rect x="10" y="37" width="230" height="28" rx="6" fill="moc-soft"/><text x="20" y="56" font-size="14" fill="ink">nói “Bắt đầu!” trong 1 giây</text><rect x="10" y="68" width="122" height="28" rx="6" fill="bad-soft"/><text x="20" y="87" font-size="14" fill="ink">lặp lại 4 lần</text><rect x="28" y="99" width="153" height="28" rx="6" fill="acc-soft"/><text x="38" y="118" font-size="14" fill="ink">di chuyển 30 bước</text><rect x="28" y="130" width="238" height="28" rx="6" fill="moc-soft"/><text x="38" y="149" font-size="14" fill="ink">nói “Tiếp nào!” trong 1 giây</text><rect x="10" y="161" width="56" height="10" rx="6" fill="bad-soft"/><rect x="10" y="174" width="207" height="28" rx="6" fill="moc-soft"/><text x="20" y="193" font-size="14" fill="ink">nói “Xong!” trong 2 giây</text><rect x="11" y="93" width="17" height="71" fill="bad-soft" stroke="none"/><line x1="10" y1="93" x2="10" y2="164"/><line x1="28" y1="96" x2="28" y2="161"/></svg>', o: ["Nhân vật nói “Bắt đầu!” 4 lần.", "Khối «di chuyển 30 bước» được thực hiện 4 lần.", "Khối «nói “Xong!” trong 2 giây» chạy sau khi lặp xong.", "Khối «nói “Tiếp nào!” trong 1 giây» chỉ chạy một lần."], a: [false, true, true, false], x: "a) Sai: khối nói “Bắt đầu!” nằm ngoài khối lặp nên chỉ chạy một lần. b) Đúng: khối này nằm trong khối «lặp lại 4 lần». c) Đúng: khối này đứng sau khối lặp. d) Sai: khối này nằm trong khối «lặp lại 4 lần» nên chạy 4 lần.", lv: 2 },
      { topic: "Chương trình máy tính", type: "num", q: "Chạy chương trình Scratch ở hình (a, b là hai biến). Nhân vật nói số nào?", svg: '<svg viewBox="0 0 320 164"><rect x="10" y="6" width="199" height="28" rx="6" fill="sun-soft"/><text x="20" y="25" font-size="14" fill="ink">khi nhấn vào lá cờ xanh</text><rect x="10" y="37" width="107" height="28" rx="6" fill="ok-soft"/><text x="20" y="56" font-size="14" fill="ink">đặt a là 12</text><rect x="10" y="68" width="130" height="28" rx="6" fill="ok-soft"/><text x="20" y="87" font-size="14" fill="ink">đặt b là a + 6</text><rect x="10" y="99" width="130" height="28" rx="6" fill="ok-soft"/><text x="20" y="118" font-size="14" fill="ink">đặt a là b − 5</text><rect x="10" y="130" width="161" height="28" rx="6" fill="moc-soft"/><text x="20" y="149" font-size="14" fill="ink">nói a trong 2 giây</text></svg>', ans: 13, x: "Lần lượt: a là 12; b là a + 6 = 18; rồi a được đặt lại là b − 5 = 13. Nhân vật nói giá trị mới của a: 13.", lv: 3 },
      { topic: "Chương trình máy tính", type: "num", q: "Chạy chương trình Scratch ở hình (s là một biến). Nhân vật nói số nào?", svg: '<svg viewBox="0 0 320 177"><rect x="10" y="6" width="199" height="28" rx="6" fill="sun-soft"/><text x="20" y="25" font-size="14" fill="ink">khi nhấn vào lá cờ xanh</text><rect x="10" y="37" width="100" height="28" rx="6" fill="ok-soft"/><text x="20" y="56" font-size="14" fill="ink">đặt s là 2</text><rect x="10" y="68" width="122" height="28" rx="6" fill="bad-soft"/><text x="20" y="87" font-size="14" fill="ink">lặp lại 3 lần</text><rect x="28" y="99" width="130" height="28" rx="6" fill="ok-soft"/><text x="38" y="118" font-size="14" fill="ink">đặt s là s + s</text><rect x="10" y="130" width="56" height="10" rx="6" fill="bad-soft"/><rect x="10" y="143" width="161" height="28" rx="6" fill="moc-soft"/><text x="20" y="162" font-size="14" fill="ink">nói s trong 2 giây</text><rect x="11" y="93" width="17" height="40" fill="bad-soft" stroke="none"/><line x1="10" y1="93" x2="10" y2="133"/><line x1="28" y1="96" x2="28" y2="130"/></svg>', ans: 16, x: "Lúc đầu s là 2. Mỗi lần lặp, s được đặt là s + s (gấp đôi): 4, 8, 16. Sau 3 lần lặp, nhân vật nói 16.", lv: 3 },
      { topic: "An toàn thông tin trên Internet", type: "mc", q: "Ở bến xe có mạng Wi-Fi miễn phí, ai cũng kết nối được mà không cần mật khẩu. Lan muốn đăng nhập tài khoản học trực tuyến để nộp bài. Cách làm an toàn hơn là:", o: ["Đợi về nhà, dùng mạng của gia đình rồi mới đăng nhập", "Đăng nhập ngay vì mạng miễn phí nào cũng an toàn", "Đăng nhập rồi gửi mật khẩu cho bạn giữ hộ", "Nhờ một người lạ ở bến xe đăng nhập giúp"], x: "Mạng công cộng thường bảo mật không tốt, kẻ xấu có thể lấy được thông tin khi em đăng nhập. Nên tránh đăng nhập tài khoản qua mạng công cộng và không đưa mật khẩu cho người khác.", lv: 3 },
      { topic: "Sơ đồ tư duy", type: "mc", q: "Sơ đồ tư duy “Kế hoạch trồng cây” Quyên vẽ tay đã kín tờ giấy, nay nhóm muốn đổi chỗ hai nhánh và chèn thêm ảnh. Cách làm hợp lí là:", o: ["Vẽ lại bằng phần mềm rồi kéo nhánh, chèn ảnh", "Dán thêm giấy rồi vẽ đè lên các nhánh cũ", "Xoá bớt vài nhánh cũ cho tờ giấy có chỗ trống", "Chuyển cả sơ đồ thành một đoạn văn thật dài"], x: "Phần mềm sơ đồ tư duy cho phép di chuyển, sửa các nhánh, thêm hình ảnh dễ dàng mà không phải vẽ lại từ đầu mỗi lần sửa. Dán đè, xoá bớt nhánh làm sơ đồ rối hoặc mất ý; đoạn văn dài không còn là sơ đồ tư duy.", lv: 2 },
      { topic: "Định dạng văn bản", type: "mc", q: "Máy tính ở nhà Nam chưa cài phần mềm soạn thảo văn bản nhưng có kết nối Internet. Nam vẫn soạn được bài bằng cách nào?", o: ["Mở phần mềm soạn thảo ngay trên trình duyệt web", "Gõ bài vào ô tìm kiếm của máy tìm kiếm rồi lưu lại", "Mở phần mềm luyện gõ phím để soạn và lưu bài", "Không có cách nào, phải đợi cài phần mềm"], x: "Có phần mềm soạn thảo văn bản dùng được ngay trên trình duyệt web khi máy có Internet, không cần cài lên máy. Ô tìm kiếm chỉ để tìm thông tin; phần mềm luyện gõ phím không dùng để soạn và lưu bài.", lv: 1 },
      { topic: "Trình bày thông tin ở dạng bảng", type: "mc", q: "Lan cần tạo một bảng 5 cột, 12 hàng. Lan nháy nút Table rồi kéo thả chuột trên lưới ô nhưng không chọn được đủ 12 hàng. Vì sao?", o: ["Vì kéo thả chỉ tạo được bảng nhiều nhất 8 hàng", "Vì bảng không được nhiều cột hơn số hàng", "Vì bảng chỉ tạo được ở thẻ Home", "Vì số hàng của bảng phải là số lẻ"], x: "Kéo thả trên lưới ô của nút Table chỉ tạo được bảng có nhiều nhất 10 cột, 8 hàng. Bảng lớn hơn thì chọn Insert Table rồi gõ số cột, số hàng.", lv: 2 },
      { topic: "Tìm kiếm và thay thế", type: "mc", q: "Lan muốn đổi chữ “bạn” thành “cậu” ở một vài chỗ trong bài, các chỗ khác giữ nguyên. Trong hộp thoại Find and Replace, Lan nháy nút nào để thay lần lượt từng chỗ cần đổi?", o: ["Replace", "Replace All", "Cancel", "More >>"], x: "Nút Replace thay chỗ đang được tìm thấy rồi chuyển tới chỗ tiếp theo, nên Lan thay được lần lượt từng chỗ mình muốn. Replace All thay mọi chỗ cùng lúc, kể cả chỗ cần giữ nguyên; Cancel đóng hộp thoại; More >> mở thêm các lựa chọn tìm kiếm.", lv: 1 }
    ]
  },
  "tin6-ck2-de2": {
    note: "Sách Kết nối tri thức, học kì II: Chủ đề 6 Giải quyết vấn đề với sự trợ giúp của máy tính (Bài 15 Thuật toán, Bài 16 Các cấu trúc điều khiển, Bài 17 Chương trình máy tính); ôn Bài 9–13 (an toàn thông tin trên Internet, sơ đồ tư duy, định dạng văn bản, trình bày thông tin ở dạng bảng, tìm kiếm và thay thế). Đề không có phần thực hành trên máy. 10 câu Biết, 8 câu Hiểu, 7 câu Vận dụng. Có lời giải từng câu.",
    questions: [
      { topic: "Thuật toán", type: "mc", q: "Thuật toán đếm số bạn nữ trong danh sách lớp 6A. Đầu ra của thuật toán là:", o: ["Số bạn nữ của lớp 6A", "Danh sách học sinh lớp 6A", "Tên bạn lớp trưởng lớp 6A", "Số bàn học của lớp 6A"], x: "Đầu ra là kết quả thuật toán tạo ra khi làm xong các bước: ở đây là số bạn nữ của lớp 6A.", lv: 1 },
      { topic: "Thuật toán", type: "mc", q: "Để mô tả cùng một cách làm, Lan viết các bước 1, 2, 3 bằng lời, còn Hùng vẽ các hình nối với nhau bằng mũi tên. Nhận xét đúng là:", o: ["Cả hai đều mô tả thuật toán, theo hai cách", "Chỉ cách của Lan là mô tả thuật toán", "Chỉ cách của Hùng là mô tả thuật toán", "Cả hai cách đều không mô tả thuật toán"], x: "Có hai cách mô tả thuật toán: liệt kê các bước bằng ngôn ngữ tự nhiên (như Lan) và vẽ sơ đồ khối (như Hùng).", lv: 1 },
      { topic: "Thuật toán", type: "mc", q: "Theo sơ đồ khối ở hình, ngay sau bước “Cho nước vào bình” là bước nào?", svg: '<svg viewBox="0 0 320 292"><polyline points="160,36 160,56" fill="none"/><polygon points="160,56 155,47 165,47" fill="ink"/><polyline points="160,86 160,106" fill="none"/><polygon points="160,106 155,97 165,97" fill="ink"/><polyline points="160,136 160,156" fill="none"/><polygon points="160,156 155,147 165,147" fill="ink"/><polyline points="160,186 160,206" fill="none"/><polygon points="160,206 155,197 165,197" fill="ink"/><polyline points="160,236 160,256" fill="none"/><polygon points="160,256 155,247 165,247" fill="ink"/><ellipse cx="160" cy="21" rx="50" ry="15" fill="moc-soft"/><text x="160" y="26" text-anchor="middle" font-size="14" fill="ink">Bắt đầu</text><rect x="70" y="56" width="180" height="30" fill="sun-soft"/><text x="160" y="76" text-anchor="middle" font-size="14" fill="ink">Lấy bình tưới</text><rect x="70" y="106" width="180" height="30" fill="sun-soft"/><text x="160" y="126" text-anchor="middle" font-size="14" fill="ink">Cho nước vào bình</text><rect x="70" y="156" width="180" height="30" fill="sun-soft"/><text x="160" y="176" text-anchor="middle" font-size="14" fill="ink">Tưới quanh gốc cây</text><rect x="70" y="206" width="180" height="30" fill="sun-soft"/><text x="160" y="226" text-anchor="middle" font-size="14" fill="ink">Cất bình tưới</text><ellipse cx="160" cy="271" rx="50" ry="15" fill="moc-soft"/><text x="160" y="276" text-anchor="middle" font-size="14" fill="ink">Kết thúc</text></svg>', o: ["Tưới quanh gốc cây", "Lấy bình tưới", "Cất bình tưới", "Kết thúc"], x: "Đi theo mũi tên từ bước “Cho nước vào bình” thì tới bước “Tưới quanh gốc cây”.", lv: 1 },
      { topic: "Thuật toán", type: "mc", q: "Bản hướng dẫn giặt khăn mặt của Nam có bước “Cho một ít xà phòng vào chậu nước”. Bước này chưa tốt vì:", o: ["Chưa rõ ràng, không biết cho bao nhiêu xà phòng", "Giặt khăn không mô tả được bằng thuật toán", "Bước có xà phòng phải đứng đầu thuật toán", "Thuật toán không được có bước nào về nước"], x: "Mỗi chỉ dẫn trong thuật toán cần cụ thể, rõ ràng. “Một ít” là chưa rõ, nên ghi cụ thể như “một thìa nhỏ xà phòng”.", lv: 2 },
      { topic: "Thuật toán", type: "tf4", q: "Sơ đồ khối ở hình mô tả thuật toán đổi độ dài từ xăng-ti-mét sang mét. Mỗi ý sau đúng hay sai?", svg: '<svg viewBox="0 0 320 242"><polyline points="160,36 160,56" fill="none"/><polygon points="160,56 155,47 165,47" fill="ink"/><polyline points="160,86 160,106" fill="none"/><polygon points="160,106 155,97 165,97" fill="ink"/><polyline points="160,136 160,156" fill="none"/><polygon points="160,156 155,147 165,147" fill="ink"/><polyline points="160,186 160,206" fill="none"/><polygon points="160,206 155,197 165,197" fill="ink"/><ellipse cx="160" cy="21" rx="50" ry="15" fill="moc-soft"/><text x="160" y="26" text-anchor="middle" font-size="14" fill="ink">Bắt đầu</text><polygon points="75,56 255,56 245,86 65,86" fill="ioe-soft"/><text x="160" y="76" text-anchor="middle" font-size="14" fill="ink">Nhập độ dài d (cm)</text><rect x="90" y="106" width="140" height="30" fill="sun-soft"/><text x="160" y="126" text-anchor="middle" font-size="14" fill="ink">m ← d : 100</text><polygon points="95,156 235,156 225,186 85,186" fill="ioe-soft"/><text x="160" y="176" text-anchor="middle" font-size="14" fill="ink">Thông báo m</text><ellipse cx="160" cy="221" rx="50" ry="15" fill="moc-soft"/><text x="160" y="226" text-anchor="middle" font-size="14" fill="ink">Kết thúc</text></svg>', o: ["Đầu vào của thuật toán là độ dài d, tính bằng xăng-ti-mét.", "Sơ đồ có hai bước xử lí.", "Đầu ra của thuật toán là m, độ dài tính bằng mét.", "Bước “Thông báo m” được thực hiện trước bước “m ← d : 100”."], a: [true, false, true, false], x: "a) Đúng: hình bình hành đầu tiên nhập độ dài d (cm). b) Sai: chỉ có một bước xử lí là m ← d : 100. c) Đúng: thuật toán thông báo m, là độ dài d đã đổi ra mét. d) Sai: phải tính m xong mới thông báo được m.", lv: 2 },
      { topic: "Thuật toán", type: "mc", q: "Sơ đồ khối ở hình mô tả thuật toán tính vận tốc v của một xe đạp. Bước còn thiếu ở ô “?” là:", svg: '<svg viewBox="0 0 320 256"><polyline points="160,36 160,56" fill="none"/><polygon points="160,56 155,47 165,47" fill="ink"/><polyline points="160,100 160,120" fill="none"/><polygon points="160,120 155,111 165,111" fill="ink"/><polyline points="160,150 160,170" fill="none"/><polygon points="160,170 155,161 165,161" fill="ink"/><polyline points="160,200 160,220" fill="none"/><polygon points="160,220 155,211 165,211" fill="ink"/><ellipse cx="160" cy="21" rx="50" ry="15" fill="moc-soft"/><text x="160" y="26" text-anchor="middle" font-size="14" fill="ink">Bắt đầu</text><polygon points="55,56 275,56 265,100 45,100" fill="ioe-soft"/><text x="160" y="74.5" text-anchor="middle" font-size="14" fill="ink">Nhập quãng đường s (km),</text><text x="160" y="91.5" text-anchor="middle" font-size="14" fill="ink">thời gian t (giờ)</text><rect x="95" y="120" width="130" height="30" fill="sun-soft"/><text x="160" y="140" text-anchor="middle" font-size="14" fill="ink">?</text><polygon points="95,170 235,170 225,200 85,200" fill="ioe-soft"/><text x="160" y="190" text-anchor="middle" font-size="14" fill="ink">Thông báo v</text><ellipse cx="160" cy="235" rx="50" ry="15" fill="moc-soft"/><text x="160" y="240" text-anchor="middle" font-size="14" fill="ink">Kết thúc</text></svg>', o: ["v ← s : t", "v ← s × t", "v ← s + t", "s ← v : t"], x: "Vận tốc bằng quãng đường chia cho thời gian: v = s : t. Bước này cần đứng sau bước nhập s, t và trước bước thông báo v.", lv: 3 },
      { topic: "Thuật toán", type: "num", q: "Lớp 6A xếp mỗi bàn đúng 2 học sinh. Thuật toán ở hình thông báo b = 18. Số học sinh n đã được nhập là bao nhiêu?", svg: '<svg viewBox="0 0 320 242"><polyline points="160,36 160,56" fill="none"/><polygon points="160,56 155,47 165,47" fill="ink"/><polyline points="160,86 160,106" fill="none"/><polygon points="160,106 155,97 165,97" fill="ink"/><polyline points="160,136 160,156" fill="none"/><polygon points="160,156 155,147 165,147" fill="ink"/><polyline points="160,186 160,206" fill="none"/><polygon points="160,206 155,197 165,197" fill="ink"/><ellipse cx="160" cy="21" rx="50" ry="15" fill="moc-soft"/><text x="160" y="26" text-anchor="middle" font-size="14" fill="ink">Bắt đầu</text><polygon points="75,56 255,56 245,86 65,86" fill="ioe-soft"/><text x="160" y="76" text-anchor="middle" font-size="14" fill="ink">Nhập số học sinh n</text><rect x="95" y="106" width="130" height="30" fill="sun-soft"/><text x="160" y="126" text-anchor="middle" font-size="14" fill="ink">b ← n : 2</text><polygon points="95,156 235,156 225,186 85,186" fill="ioe-soft"/><text x="160" y="176" text-anchor="middle" font-size="14" fill="ink">Thông báo b</text><ellipse cx="160" cy="221" rx="50" ry="15" fill="moc-soft"/><text x="160" y="226" text-anchor="middle" font-size="14" fill="ink">Kết thúc</text></svg>', ans: 36, unit: "học sinh", x: "b ← n : 2 mà b = 18 nên n là số chia cho 2 được 18: n = 18 × 2 = 36 (học sinh).", lv: 3 },
      { topic: "Các cấu trúc điều khiển", type: "mc", q: "Câu nào dưới đây mô tả một công việc có cấu trúc lặp?", o: ["Tổ trực nhật lau từng bộ bàn ghế cho đến khi hết bàn", "Nếu có bài kiểm tra thì Nam ôn bài kĩ hơn", "Nam ăn sáng xong rồi đi học", "Nếu bút hết mực thì Nam thay ruột bút, còn không thì viết tiếp"], x: "Lau từng bộ bàn ghế cho đến khi hết bàn là làm đi làm lại một việc nhiều lần: đó là cấu trúc lặp.", lv: 1 },
      { topic: "Các cấu trúc điều khiển", type: "mc", q: "Cấu trúc rẽ nhánh còn được gọi là:", o: ["Cấu trúc lựa chọn", "Cấu trúc nối tiếp", "Cấu trúc vòng tròn", "Cấu trúc dữ liệu"], x: "Theo sách, cấu trúc rẽ nhánh còn gọi là cấu trúc lựa chọn: tuỳ điều kiện đúng hay sai mà chọn nhánh để thực hiện tiếp.", lv: 1 },
      { topic: "Các cấu trúc điều khiển", type: "mc", q: "Theo sơ đồ khối ở hình, nếu hôm nay có tiết Thể dục thì Nam làm việc gì trước khi đi học?", svg: '<svg viewBox="0 0 320 318"><polyline points="160,36 160,60" fill="none"/><polygon points="160,60 155,51 165,51" fill="ink"/><polyline points="90,92 74,92 74,150" fill="none"/><polygon points="74,150 69,141 79,141" fill="ink"/><text x="60" y="84" text-anchor="middle" font-size="13" fill="muted">Đúng</text><polyline points="230,92 246,92 246,150" fill="none"/><polygon points="246,150 241,141 251,141" fill="ink"/><text x="260" y="84" text-anchor="middle" font-size="13" fill="muted">Sai</text><polyline points="74,194 74,211 160,211 160,229" fill="none"/><polygon points="160,229 155,220 165,220" fill="ink"/><polyline points="246,194 246,211 160,211 160,229" fill="none"/><polygon points="160,229 155,220 165,220" fill="ink"/><polyline points="160,259 160,281" fill="none"/><polygon points="160,281 155,272 165,272" fill="ink"/><ellipse cx="160" cy="21" rx="50" ry="15" fill="moc-soft"/><text x="160" y="26" text-anchor="middle" font-size="14" fill="ink">Bắt đầu</text><polygon points="160,60 230,92 160,124 90,92" fill="ok-soft"/><text x="160" y="88.5" text-anchor="middle" font-size="14" fill="ink">Có tiết</text><text x="160" y="105.5" text-anchor="middle" font-size="14" fill="ink">Thể dục?</text><rect x="6" y="150" width="136" height="44" fill="sun-soft"/><text x="74" y="168.5" text-anchor="middle" font-size="14" fill="ink">Mặc đồng phục</text><text x="74" y="185.5" text-anchor="middle" font-size="14" fill="ink">thể thao</text><rect x="178" y="150" width="136" height="44" fill="sun-soft"/><text x="246" y="168.5" text-anchor="middle" font-size="14" fill="ink">Mặc đồng phục</text><text x="246" y="185.5" text-anchor="middle" font-size="14" fill="ink">thường</text><rect x="100" y="229" width="120" height="30" fill="sun-soft"/><text x="160" y="249" text-anchor="middle" font-size="14" fill="ink">Đi học</text><ellipse cx="160" cy="296" rx="50" ry="15" fill="moc-soft"/><text x="160" y="301" text-anchor="middle" font-size="14" fill="ink">Kết thúc</text></svg>', o: ["Mặc đồng phục thể thao", "Mặc đồng phục thường", "Mặc cả hai bộ đồng phục", "Không đi học"], x: "Có tiết Thể dục thì điều kiện đúng, đi theo nhánh Đúng: mặc đồng phục thể thao, rồi đi học.", lv: 1 },
      { topic: "Các cấu trúc điều khiển", type: "match", q: "Nối mỗi cấu trúc điều khiển với ví dụ phù hợp.", l: ["Cấu trúc tuần tự", "Cấu trúc rẽ nhánh", "Cấu trúc lặp"], r: ["Rửa tay bằng xà phòng, tráng lại bằng nước sạch, lau khô tay", "Nếu nồi canh sôi thì vặn nhỏ lửa", "Chạy quanh sân trường cho đến khi đủ 5 vòng"], x: "Rửa tay: các bước làm lần lượt, mỗi bước một lần (tuần tự). Vặn nhỏ lửa chỉ khi canh đã sôi: có điều kiện (rẽ nhánh). Chạy từng vòng cho đến khi đủ 5 vòng: làm lại nhiều lần (lặp).", lv: 2 },
      { topic: "Các cấu trúc điều khiển", type: "tf4", q: "Thực hiện thuật toán ở hình. Mỗi ý sau đúng hay sai?", svg: '<svg viewBox="0 0 320 398"><polyline points="160,36 160,55" fill="none"/><polygon points="160,55 155,46 165,46" fill="ink"/><polyline points="160,85 160,113" fill="none"/><polygon points="160,113 155,104 165,104" fill="ink"/><polyline points="160,163 160,189" fill="none"/><polygon points="160,189 155,180 165,180" fill="ink"/><text x="186" y="180" text-anchor="middle" font-size="13" fill="muted">Đúng</text><polyline points="160,219 160,239" fill="none"/><polygon points="160,239 155,230 165,230" fill="ink"/><polyline points="90,254 30,254 30,102 160,102 160,113" fill="none"/><polygon points="160,113 155,104 165,104" fill="ink"/><polyline points="225,138 296,138 296,290 160,290 160,307" fill="none"/><polygon points="160,307 155,298 165,298" fill="ink"/><text x="284" y="130" text-anchor="middle" font-size="13" fill="muted">Sai</text><polyline points="160,337 160,361" fill="none"/><polygon points="160,361 155,352 165,352" fill="ink"/><ellipse cx="160" cy="21" rx="50" ry="15" fill="moc-soft"/><text x="160" y="26" text-anchor="middle" font-size="14" fill="ink">Bắt đầu</text><rect x="85" y="55" width="150" height="30" fill="sun-soft"/><text x="160" y="75" text-anchor="middle" font-size="14" fill="ink">S ← 0, i ← 1</text><polygon points="160,113 225,138 160,163 95,138" fill="ok-soft"/><text x="160" y="143" text-anchor="middle" font-size="14" fill="ink">i ≤ 4?</text><rect x="90" y="189" width="140" height="30" fill="sun-soft"/><text x="160" y="209" text-anchor="middle" font-size="14" fill="ink">S ← S + i</text><rect x="90" y="239" width="140" height="30" fill="sun-soft"/><text x="160" y="259" text-anchor="middle" font-size="14" fill="ink">i ← i + 1</text><polygon points="95,307 235,307 225,337 85,337" fill="ioe-soft"/><text x="160" y="327" text-anchor="middle" font-size="14" fill="ink">Thông báo S</text><ellipse cx="160" cy="376" rx="50" ry="15" fill="moc-soft"/><text x="160" y="381" text-anchor="middle" font-size="14" fill="ink">Kết thúc</text></svg>', o: ["Bước “S ← S + i” được thực hiện 4 lần.", "Sau mỗi lần làm bước “i ← i + 1”, thuật toán quay lại kiểm tra điều kiện “i ≤ 4?”.", "Nếu bỏ bước “i ← i + 1” thì thuật toán vẫn dừng sau 4 lần lặp.", "Khi i = 5, thuật toán thực hiện thêm một lần bước “S ← S + i”."], a: [true, true, false, false], x: "a) Đúng: với i = 1, 2, 3, 4 điều kiện i ≤ 4 đúng nên bước “S ← S + i” được làm 4 lần; khi i = 5 thì dừng. b) Đúng: mũi tên từ bước “i ← i + 1” quay về hình thoi. c) Sai: không tăng i thì i luôn bằng 1, điều kiện luôn đúng, thuật toán lặp mãi. d) Sai: i = 5 thì đi theo nhánh Sai, không cộng thêm.", lv: 2 },
      { topic: "Các cấu trúc điều khiển", type: "mc", q: "Hà làm theo hướng dẫn: “Nếu pin điện thoại còn dưới 20% thì cắm sạc.” Lúc này pin điện thoại còn 60%. Theo hướng dẫn đó, Hà sẽ:", o: ["Không cắm sạc, làm tiếp việc khác", "Vẫn cắm sạc như mọi khi", "Đợi pin xuống dưới 20% rồi mới làm việc khác", "Cắm sạc rồi rút ra ngay"], x: "Điều kiện “pin còn dưới 20%” sai (60% không dưới 20%), nên Hà bỏ qua việc cắm sạc và làm tiếp các việc sau.", lv: 2 },
      { topic: "Các cấu trúc điều khiển", type: "num", q: "Mỗi tuần Hà bỏ vào lợn đất 15 nghìn đồng. Thuật toán ở hình tính số tuần k để Hà có ít nhất 100 nghìn đồng (T tính bằng nghìn đồng). Thuật toán thông báo k bằng bao nhiêu?", svg: '<svg viewBox="0 0 320 398"><polyline points="160,36 160,55" fill="none"/><polygon points="160,55 155,46 165,46" fill="ink"/><polyline points="160,85 160,113" fill="none"/><polygon points="160,113 155,104 165,104" fill="ink"/><polyline points="160,163 160,189" fill="none"/><polygon points="160,189 155,180 165,180" fill="ink"/><text x="186" y="180" text-anchor="middle" font-size="13" fill="muted">Đúng</text><polyline points="160,219 160,239" fill="none"/><polygon points="160,239 155,230 165,230" fill="ink"/><polyline points="90,254 30,254 30,102 160,102 160,113" fill="none"/><polygon points="160,113 155,104 165,104" fill="ink"/><polyline points="225,138 296,138 296,290 160,290 160,307" fill="none"/><polygon points="160,307 155,298 165,298" fill="ink"/><text x="284" y="130" text-anchor="middle" font-size="13" fill="muted">Sai</text><polyline points="160,337 160,361" fill="none"/><polygon points="160,361 155,352 165,352" fill="ink"/><ellipse cx="160" cy="21" rx="50" ry="15" fill="moc-soft"/><text x="160" y="26" text-anchor="middle" font-size="14" fill="ink">Bắt đầu</text><rect x="85" y="55" width="150" height="30" fill="sun-soft"/><text x="160" y="75" text-anchor="middle" font-size="14" fill="ink">T ← 0, k ← 0</text><polygon points="160,113 225,138 160,163 95,138" fill="ok-soft"/><text x="160" y="143" text-anchor="middle" font-size="14" fill="ink">T &lt; 100?</text><rect x="90" y="189" width="140" height="30" fill="sun-soft"/><text x="160" y="209" text-anchor="middle" font-size="14" fill="ink">T ← T + 15</text><rect x="90" y="239" width="140" height="30" fill="sun-soft"/><text x="160" y="259" text-anchor="middle" font-size="14" fill="ink">k ← k + 1</text><polygon points="95,307 235,307 225,337 85,337" fill="ioe-soft"/><text x="160" y="327" text-anchor="middle" font-size="14" fill="ink">Thông báo k</text><ellipse cx="160" cy="376" rx="50" ry="15" fill="moc-soft"/><text x="160" y="381" text-anchor="middle" font-size="14" fill="ink">Kết thúc</text></svg>', ans: 7, unit: "tuần", x: "Sau mỗi lần lặp, T lần lượt bằng 15, 30, 45, 60, 75, 90, 105 và k bằng 1, 2, …, 7. Khi T = 105 thì T < 100 sai nên dừng và thông báo k = 7.", lv: 3 },
      { topic: "Các cấu trúc điều khiển", type: "mc", q: "Máy bán nước tự động nhận từng tờ tiền: với mỗi tờ, nếu tờ tiền bị rách thì trả lại, còn không thì cộng vào số tiền đã nhận; máy làm như vậy cho đến khi đủ tiền. Cách làm việc của máy cần những cấu trúc nào?", o: ["Lặp, bên trong có rẽ nhánh", "Tuần tự, không có điều kiện nào", "Rẽ nhánh, không cần lặp lại", "Lặp, không cần kiểm tra điều kiện"], x: "Nhận từng tờ cho đến khi đủ tiền là lặp; với mỗi tờ, kiểm tra rách hay không để trả lại hoặc cộng vào là rẽ nhánh. Rẽ nhánh nằm bên trong vòng lặp.", lv: 3 },
      { topic: "Chương trình máy tính", type: "mc", q: "Khánh đã vẽ sơ đồ khối của một thuật toán trên giấy. Muốn máy tính thực hiện được thuật toán đó, Khánh cần:", o: ["Viết lại thuật toán bằng một ngôn ngữ lập trình", "Chụp ảnh sơ đồ khối rồi lưu vào máy tính", "Đọc to từng bước của sơ đồ cho máy tính nghe", "Gõ lại các bước bằng tiếng Việt vào phần mềm soạn thảo"], x: "Máy tính chỉ làm theo chương trình viết bằng ngôn ngữ lập trình (ví dụ Scratch); ảnh chụp sơ đồ, lời đọc hay các bước gõ bằng tiếng Việt thì máy tính không thực hiện được. Vì vậy cần viết thuật toán thành chương trình.", lv: 1 },
      { topic: "Chương trình máy tính", type: "mc", q: "Trong ngôn ngữ lập trình trực quan Scratch, em tạo chương trình bằng cách:", o: ["Kéo thả, ghép các khối lệnh với nhau", "Gõ từng câu lệnh bằng tiếng Anh vào máy", "Chép mã lệnh từ sách vào phần mềm soạn thảo", "Vẽ sơ đồ khối rồi lưu thành tệp ảnh"], x: "Với Scratch, em kéo các khối lệnh có sẵn ra vùng lập trình rồi ghép chúng lại thành chương trình, không phải gõ từng câu lệnh.", lv: 1 },
      { topic: "Chương trình máy tính", type: "mc", q: "Chương trình Scratch ở hình sử dụng những cấu trúc điều khiển nào?", svg: '<svg viewBox="0 0 320 177"><rect x="10" y="6" width="199" height="28" rx="6" fill="sun-soft"/><text x="20" y="25" font-size="14" fill="ink">khi nhấn vào lá cờ xanh</text><rect x="10" y="37" width="268" height="28" rx="6" fill="ioe-soft"/><text x="20" y="56" font-size="14" fill="ink">hỏi “Đã cho mèo ăn chưa?” và đợi</text><rect x="10" y="68" width="207" height="28" rx="6" fill="bad-soft"/><text x="20" y="87" font-size="14" fill="ink">nếu trả lời = “chưa” thì</text><rect x="28" y="99" width="284" height="28" rx="6" fill="moc-soft"/><text x="38" y="118" font-size="14" fill="ink">nói “Cho mèo ăn nhé!” trong 2 giây</text><rect x="10" y="130" width="56" height="10" rx="6" fill="bad-soft"/><rect x="10" y="143" width="276" height="28" rx="6" fill="moc-soft"/><text x="20" y="162" font-size="14" fill="ink">nói “Chúc ngày vui!” trong 2 giây</text><rect x="11" y="93" width="17" height="40" fill="bad-soft" stroke="none"/><line x1="10" y1="93" x2="10" y2="133"/><line x1="28" y1="96" x2="28" y2="130"/></svg>', o: ["Tuần tự và rẽ nhánh", "Chỉ có cấu trúc tuần tự", "Tuần tự và lặp", "Rẽ nhánh và lặp"], x: "Các khối được thực hiện lần lượt từ trên xuống (tuần tự); khối «nếu … thì» chỉ cho nhân vật nhắc khi người dùng trả lời “chưa” (rẽ nhánh). Chương trình không có khối lặp.", lv: 2 },
      { topic: "Chương trình máy tính", type: "mc", q: "Chạy chương trình Scratch ở hình, Lan gõ 20 rồi nhấn Enter. Nhân vật nói gì?", svg: '<svg viewBox="0 0 320 239"><rect x="10" y="6" width="199" height="28" rx="6" fill="sun-soft"/><text x="20" y="25" font-size="14" fill="ink">khi nhấn vào lá cờ xanh</text><rect x="10" y="37" width="292" height="28" rx="6" fill="ioe-soft"/><text x="20" y="56" font-size="14" fill="ink">hỏi “Hôm nay đọc mấy trang?” và đợi</text><rect x="10" y="68" width="145" height="28" rx="6" fill="ok-soft"/><text x="20" y="87" font-size="14" fill="ink">đặt p là trả lời</text><rect x="10" y="99" width="130" height="28" rx="6" fill="bad-soft"/><text x="20" y="118" font-size="14" fill="ink">nếu p &lt; 20 thì</text><rect x="28" y="130" width="268" height="28" rx="6" fill="moc-soft"/><text x="38" y="149" font-size="14" fill="ink">nói “Đọc thêm nhé!” trong 2 giây</text><rect x="10" y="161" width="120" height="28" rx="6" fill="bad-soft"/><text x="20" y="180" font-size="14" fill="ink">còn không thì</text><rect x="28" y="192" width="238" height="28" rx="6" fill="moc-soft"/><text x="38" y="211" font-size="14" fill="ink">nói “Giỏi lắm!” trong 2 giây</text><rect x="10" y="223" width="56" height="10" rx="6" fill="bad-soft"/><rect x="11" y="124" width="17" height="40" fill="bad-soft" stroke="none"/><line x1="10" y1="124" x2="10" y2="164"/><line x1="28" y1="127" x2="28" y2="161"/><rect x="11" y="186" width="17" height="40" fill="bad-soft" stroke="none"/><line x1="10" y1="186" x2="10" y2="226"/><line x1="28" y1="189" x2="28" y2="223"/></svg>', o: ["Giỏi lắm!", "Đọc thêm nhé!", "Nói cả hai câu, lần lượt", "Không nói gì"], x: "p = 20 nên điều kiện p < 20 sai (20 không nhỏ hơn 20). Chương trình chạy phần «còn không thì»: nhân vật nói “Giỏi lắm!”.", lv: 3 },
      { topic: "Chương trình máy tính", type: "mc", q: "Tú muốn nhân vật nói lần lượt 3, 2, 1 nhưng chương trình Scratch ở hình lại nói 3, 4, 5. Tú cần sửa thế nào?", svg: '<svg viewBox="0 0 320 177"><rect x="10" y="6" width="199" height="28" rx="6" fill="sun-soft"/><text x="20" y="25" font-size="14" fill="ink">khi nhấn vào lá cờ xanh</text><rect x="10" y="37" width="100" height="28" rx="6" fill="ok-soft"/><text x="20" y="56" font-size="14" fill="ink">đặt n là 3</text><rect x="10" y="68" width="122" height="28" rx="6" fill="bad-soft"/><text x="20" y="87" font-size="14" fill="ink">lặp lại 3 lần</text><rect x="28" y="99" width="161" height="28" rx="6" fill="moc-soft"/><text x="38" y="118" font-size="14" fill="ink">nói n trong 1 giây</text><rect x="28" y="130" width="130" height="28" rx="6" fill="ok-soft"/><text x="38" y="149" font-size="14" fill="ink">đặt n là n + 1</text><rect x="10" y="161" width="56" height="10" rx="6" fill="bad-soft"/><rect x="11" y="93" width="17" height="71" fill="bad-soft" stroke="none"/><line x1="10" y1="93" x2="10" y2="164"/><line x1="28" y1="96" x2="28" y2="161"/></svg>', o: ["Đổi «đặt n là n + 1» thành «đặt n là n − 1»", "Đổi «lặp lại 3 lần» thành «lặp lại 1 lần»", "Đổi «đặt n là 3» thành «đặt n là 1»", "Bỏ khối «nói n trong 1 giây»"], x: "Mỗi lần lặp, nhân vật nói n rồi tăng n thêm 1 nên nói 3, 4, 5. Đổi thành n − 1 thì n giảm dần: nhân vật nói 3, 2, 1.", lv: 3 },
      { topic: "An toàn thông tin trên Internet", type: "mc", q: "Hùng nhận được lời mời vào nhóm trò chuyện “Kiếm tiền dễ dàng cho học sinh” từ một tài khoản không quen biết. Hùng nên làm gì?", o: ["Từ chối lời mời và kể lại với bố mẹ", "Vào nhóm thử xem vì không mất gì", "Vào nhóm rồi mời thêm bạn bè cùng vào", "Gửi số điện thoại để được hướng dẫn"], x: "Không tham gia các hội nhóm trên mạng không rõ nguồn gốc, nhất là lời mời từ người lạ hứa hẹn kiếm tiền dễ dàng: đó thường là lừa đảo. Hãy từ chối và nói với người lớn tin cậy.", lv: 3 },
      { topic: "Sơ đồ tư duy", type: "mc", q: "Hoa đã vẽ xong sơ đồ tư duy “Ngày hội thể thao của trường” thì nhớ ra một ý mới thuộc nhánh “Môn thi đấu”. Hoa nên làm gì?", o: ["Vẽ thêm một nhánh con từ nhánh “Môn thi đấu”", "Vẽ ý mới thành nhánh nối thẳng với chủ đề chính", "Ghi ý mới vào nhánh “Thời gian”", "Bỏ ý mới đi vì sơ đồ đã có đủ các nhánh"], x: "Sơ đồ tư duy vẽ thêm được về mọi hướng: ý mới thuộc nhánh nào thì thêm một nhánh con vào đúng nhánh đó. Nối thẳng vào chủ đề chính hay ghi vào nhánh khác làm sai bố cục; không cần bỏ ý mới.", lv: 2 },
      { topic: "Định dạng văn bản", type: "mc", q: "Trường hợp nào dưới đây cho thấy phần mềm soạn thảo văn bản trực tuyến giúp làm việc cộng tác?", o: ["Cả nhóm cùng sửa một bản báo cáo, mỗi bạn ở nhà mình", "Lan in bài báo cáo ra giấy để nộp cho cô giáo", "Nam đổi phông chữ cho bài văn của riêng mình", "Hà lưu bài văn vào thẻ nhớ để mang đến lớp"], x: "Làm việc cộng tác là nhiều người cùng làm trên một tài liệu dù mỗi người ở một nơi; phần mềm soạn thảo trực tuyến cho phép làm như vậy. In bài, đổi phông chữ, lưu bài là việc một người tự làm.", lv: 1 },
      { topic: "Trình bày thông tin ở dạng bảng", type: "mc", q: "Linh muốn xoá một cột của bảng nhưng không thấy thẻ Layout của nhóm Table Tools trên dải lệnh. Lí do có thể là:", o: ["Con trỏ soạn thảo chưa đặt trong bảng", "Bảng chưa có hàng tiêu đề ở trên cùng", "Văn bản chưa được in ra giấy lần nào", "Bảng chỉ có hai cột nên không xoá được"], x: "Nhóm thẻ Table Tools (có thẻ Layout chứa các lệnh xoá, chèn hàng, cột) chỉ hiện ra khi con trỏ soạn thảo nằm trong bảng. Nháy chuột vào một ô của bảng là thấy thẻ này.", lv: 2 },
      { topic: "Tìm kiếm và thay thế", type: "mc", q: "Trong hộp thoại Find and Replace, ô Replace with dùng để gõ:", o: ["Từ, cụm từ mới sẽ thay vào chỗ tìm thấy", "Từ, cụm từ cần tìm trong văn bản", "Tên của tệp văn bản cần mở", "Số trang cần in ra giấy"], x: "Ô Find what nhận chữ cần tìm; ô Replace with nhận chữ mới sẽ thay vào những chỗ tìm thấy.", lv: 1 }
    ]
  }
});
